// Auto-generated by scripts/auto-improve.sh — do not edit manually
// Each entry is appended by the auto-improvement engine after a successful run.
export const improvements = [
  { id: 1, timestamp: "2026-03-02T12:00:00Z", category: "bug", summary: "Fix de Bruijn-Newman x-scale using gamma values instead of zero count", files: ["LiCriterionViz.jsx"], detail: "The de Bruijn-Newman heat flow visualization had its x-axis domain set to [0, numZeros+2] (the count of zeros), but plotted gamma values (imaginary parts of zeta zeros, ranging ~14 to ~1000). This caused most data points to render off-screen. Fixed by setting the domain to [0, maxGamma*1.05] so all zeros are visible." },
  { id: 2, timestamp: "2026-03-02T12:05:00Z", category: "bug", summary: "Fix Nyquist plot double-negation bug in negative frequency contour", files: ["NyquistBodeViz.jsx"], detail: "The negative frequency contour in the Nyquist plot had a double-negation bug: the loop variable t was already negative, but computeLoopGain was called with -t, making it positive again. This caused the negative frequency contour to duplicate the positive one instead of showing the correct complex-conjugate mirror. Fixed by passing t directly." },
  { id: 3, timestamp: "2026-03-02T12:10:00Z", category: "accuracy", summary: "Fix inverted sign in Riemann-Siegel Z correction term", files: ["zeta.js"], detail: "The C₀ correction term in riemannSiegelZ() used sign factor (-1)^N instead of the correct (-1)^{N-1} from Edwards' formula. This inverted the correction for every value of N, making the approximation worse rather than better. The fix changes (N%2===0 ? 1 : -1) to (N%2===0 ? -1 : 1), properly improving accuracy from O(t^{-1/4}) to O(t^{-3/4})." },
  { id: 4, timestamp: "2026-03-02T12:15:00Z", category: "accuracy", summary: "Fix incorrect claim that Euler product converges in the critical strip", files: ["EulerProductViz.jsx"], detail: "The Euler product explainer incorrectly stated that convergence is 'conditional' in the critical strip and that partial products 'oscillate before settling.' The Euler product prod_p (1-p^{-s})^{-1} only converges for Re(s) > 1 and diverges in the critical strip. Updated the text to correctly state divergence and clarify that the true |zeta(s)| reference line uses Borwein-accelerated analytic continuation." },
  { id: 5, timestamp: "2026-03-02T12:20:00Z", category: "ux", summary: "Add axis tick labels to Energy Landscape heatmap canvas", files: ["EnergyLandscapeViz.jsx"], detail: "The Energy Landscape heatmap had no axis tick marks or labels on its edges, making it hard to read precise σ and t values. Replaced the plain-text range overlay ('σ: 0.05 → 0.95', 't: 0.5 → 50') with proper tick labels along the bottom edge (σ from 0.1 to 0.9) and left edge (t values), each with semi-transparent backgrounds for readability over the heatmap." },
  { id: 6, timestamp: "2026-03-02T12:25:00Z", category: "ux", summary: "Prevent t-range sliders from crossing in ZetaLandscapeViz", files: ["ZetaLandscapeViz.jsx"], detail: "The 't range start' and 't range end' sliders in the Zeta Landscape visualization had no constraint preventing the start value from exceeding the end value. This would produce a zero or negative step size, breaking both the critical-line Z(t) plot and the heatmap. Added clamping so start is always at least 5 less than end." },
  { id: 7, timestamp: "2026-03-02T12:30:00Z", category: "visual", summary: "Add legend and improve unit circle visibility in Nyquist plot", files: ["NyquistBodeViz.jsx"], detail: "The unit circle reference in the Nyquist plot was drawn in #2a3050 (nearly invisible against the dark background), making it useless as a gain margin reference. Changed the stroke to #64748b with increased width and added a '|L|=1' label. Also added a four-item legend identifying the positive/negative frequency contours, unit circle, and critical point at −1." },
  { id: 8, timestamp: "2026-03-02T12:35:00Z", category: "visual", summary: "Add missing legend to frequency mode in PrimeGapCouplingViz", files: ["PrimeGapCouplingViz.jsx"], detail: "The 'Oscillator Frequencies' mode in PrimeGapCouplingViz had no legend, unlike the coupling and gap modes which both had one. Users couldn't tell what the colored dots or the gray dashed curve represented. Added a legend showing the ω = log(p) data points and the log(x) reference curve, matching the visual style of the existing legends in the other modes." },
  { id: 9, timestamp: "2026-03-02T12:40:00Z", category: "performance", summary: "Hoist loop-invariant Math.log and Math.pow out of explicitFormulaTerms zero loop", files: ["primes.js"], detail: "In explicitFormulaTerms(), Math.log(x) and Math.pow(x, sigma) were computed inside the per-zero loop despite depending only on the outer parameters x and sigma. With 200 zeros, this caused 199 redundant log and pow calls per invocation. Hoisted both computations before the loop, reducing work proportional to the number of zeros." },
  { id: 10, timestamp: "2026-03-02T12:45:00Z", category: "performance", summary: "Memoize expensive energyLandscape computation to avoid recomputing on metric change", files: ["EnergyLandscapeViz.jsx"], detail: "The Energy Landscape heatmap recomputed the full 3,721-cell grid (each requiring two ladder evaluations over N primes) every time the metric dropdown changed, even though the landscape data only depends on numPrimes and tMax. Extracted the energyLandscape() call into a useMemo with [numPrimes, tMax] dependencies, so switching between Energy/Mismatch/Direct/Dual metrics now only re-renders the canvas with cached data instead of recomputing ~220k complex operations." },
  { id: 11, timestamp: "2026-03-02T12:50:00Z", category: "content", summary: "Add mode physics explainer cards to ModesPage explaining damped oscillation anatomy and RH equipartition", files: ["ModesPage.jsx"], detail: "The ModesPage showed the explicit formula but didn't explain what each term means physically. Added two explainer cards: 'Anatomy of a Mode' decomposes x^ρ = x^σ · e^{iγ log x} to explain how σ controls amplitude decay and γ controls oscillation frequency, and 'Why σ = 1/2 Matters' explains that RH implies all modes share the same decay rate, giving an energy equipartition interpretation of the critical line." },
  { id: 12, timestamp: "2026-03-02T12:55:00Z", category: "content", summary: "Add spectral decomposition and impulse response explainer cards to explicit formula section", files: ["HamiltonianPage.jsx"], detail: "The Explicit Formula section on the Hamiltonian page ended abruptly after the visualization with no explanatory content, unlike every other section which had two-column cards. Added three cards: 'Spectral Decomposition' showing how each zero ρ = 1/2 + iγ contributes a damped sinusoid with frequency γ and decay x^{1/2}; 'Convergence & Error' explaining that RH gives the optimal O(√x log²x) error bound; and 'Circuit Interpretation: Impulse Response' connecting the explicit formula to the oscillator chain's impulse response where lossless modes at σ = 1/2 give optimal reconstruction." },
  { id: 13, timestamp: "2026-03-02T13:00:00Z", category: "bug", summary: "Fix Q-factor formula that was wrong by a factor of log(p)", files: ["oscillators.js", "supercritical.js"], detail: "The Q-factor computation used Q = ω/(2σ) = log(p)/(2σ), which varies per prime and gives Q ≠ 1 at σ = 1/2 (e.g. Q = 0.69 for p=2, Q = 1.61 for p=5). The correct formula is Q = ω/bandwidth = ω/(2σω) = 1/(2σ), which is prime-independent and equals 1 at the critical line — the central 'critical coupling' property of the oscillator model. Fixed in both oscillators.js and supercritical.js." },
  { id: 14, timestamp: "2026-03-02T13:05:00Z", category: "bug", summary: "Fix wrong sign of imaginary part in dual ladder construction in WaveSimViz", files: ["WaveSimViz.jsx"], detail: "Three tabs in WaveSimViz (Per-Prime Waves, Wave Interference, Phase & Delay) constructed sDual as [1−σ, t] instead of the correct [1−σ, −t]. The functional equation maps s = σ+it to 1−s = (1−σ)−it, so the dual point must negate the imaginary part. The code was computing ζ(1−σ+it) — the complex conjugate of the correct value — causing all dual ladder waves, interference patterns, and group delay comparisons to display incorrect values." },
  { id: 15, timestamp: "2026-03-02T13:10:00Z", category: "accuracy", summary: "Fix specific heat formula dividing by σ² instead of multiplying", files: ["supercritical.js"], detail: "The specific heat computation used C_v = (∂²log Z/∂β²) / β² but the correct thermodynamic identity is C_v = β² · ∂²log Z/∂β² where β = σ. The code divided d2LogZ by sigma² instead of multiplying, making the result off by a factor of σ⁴. Also corrected the comment from the wrong formula C = -T²·∂²log(Z)/∂T² to the correct C_v = β²·∂²log(Z)/∂β²." },
  { id: 16, timestamp: "2026-03-02T13:15:00Z", category: "accuracy", summary: "Replace Riemann-sum unfolding with exact Weyl-law formula in number variance", files: ["GUEStatisticsViz.jsx"], detail: "The number variance computation unfolded zeta zeros using a forward-Euler Riemann sum of the local density, which introduced systematic error especially for the first few zeros where density changes rapidly. Replaced with the exact smooth counting function N̂(γ) = (γ/2π)log(γ/2π) − γ/2π + 7/8, the Weyl-law asymptotic that maps zeros to uniformly spaced positions. This produces more accurate unfolded coordinates and improves the number variance plot's agreement with the GUE prediction curve." },
  { id: 17, timestamp: "2026-03-02T13:20:00Z", category: "ux", summary: "Add critical line color indicator to all σ sliders in Fourier Domain tabs", files: ["FourierDomainViz.jsx"], detail: "The three σ sliders in the Fourier Domain page (Frequency Response, Spectral Energy, Prime Harmonics) showed the numeric value but gave no visual feedback about proximity to the critical line σ = 0.5. Added the same color-coded indicator used in WaveSimViz: green when σ ≈ 0.5 (within 0.02), yellow when close (within 0.15), and red when far away. Applied via accentColor on the slider track and colored bold text on the value display." },
  { id: 18, timestamp: "2026-03-02T13:25:00Z", category: "visual", summary: "Add missing y-axis labels to all three modes of ScatteringMatrixViz", files: ["ScatteringMatrixViz.jsx"], detail: "The scattering matrix visualization had no y-axis labels on any of its three modes (magnitude, reflection, phase), making it harder to read the plotted quantities. Added rotated y-axis labels: '|χ(s)|' for magnitude mode, 'Γ' for reflection coefficient mode, and 'arg(χ) (degrees)' for phase mode, matching the axis label style used in ExplicitFormulaViz and other visualizations." },
  { id: 19, timestamp: "2026-03-02T13:30:00Z", category: "visual", summary: "Fix number-variance legend to match plot styling (dashed Poisson line, data point circles)", files: ["GUEStatisticsViz.jsx"], detail: "The number-variance mode legend in GUEStatisticsViz showed all three entries as solid lines, but the actual plot uses different styles: zeta zeros are plotted with line + circles, the GUE prediction is a solid curve, and the Poisson reference is a dashed line. Updated the legend to match: added stroke-dasharray '6,4' to the Poisson legend entry and added small circle markers to the zeta zeros legend entry, so the legend accurately represents how data appears in the plot." },
  { id: 20, timestamp: "2026-03-02T13:35:00Z", category: "performance", summary: "Hoist oscillatorStage calls out of per-pixel loop in WaveInterferenceTab animation", files: ["WaveSimViz.jsx"], detail: "In WaveInterferenceTab's draw function, oscillatorStage(p, s) and oscillatorStage(p, sDual) were called inside the inner x-point loop (400 iterations) for every prime, even though the results depend only on the prime and s — not the loop variable j. With numPrimes=8, this caused 6,400 redundant oscillatorStage calls per frame (each involving cPow with log/exp/trig). Hoisted the per-prime computations into a precomputed array before the loop, reducing calls from 400×numPrimes×2 to just numPrimes×2." },
  { id: 21, timestamp: "2026-03-02T13:40:00Z", category: "content", summary: "Add Hamiltonian anatomy and caveat explainer cards to SimulatorPage", files: ["SimulatorPage.jsx"], detail: "The SimulatorPage had only a brief tab-listing card with no explanation of the Hamiltonian's three terms or their physical meaning. Added two cards: 'Anatomy of the Hamiltonian' breaks down the oscillator energy, impedance mismatch, and bridge unitarity penalty terms in a two-column layout explaining what each enforces; 'Important Caveat' clarifies that the Hamiltonian is engineered with the minimum at σ=1/2 by construction and is not a proof of RH, but a pedagogical tool for visualizing functional equation symmetries." },
  { id: 22, timestamp: "2026-03-02T13:45:00Z", category: "bug", summary: "Fix heat-evolved Xi chart clipping negative values, hiding zero crossings", files: ["SupercriticalViz.jsx"], detail: "The Heat Flow tab's bottom chart used y-domain [0, yMax], but heatEvolvedXi() returns signed values that change sign at zeros — the whole point of the visualization. Negative portions were clipped below the x-axis, making zero crossings invisible. Fixed by using domain [-yMax, yMax] with yMax based on Math.abs, changed the area fill baseline from the bottom edge to y(0), added a dashed zero baseline, and corrected the title from |Hτ(t)| to Hτ(t)." },
  { id: 23, timestamp: "2026-03-02T13:50:00Z", category: "bug", summary: "Fix heatEvolvedXi using Re(ζ) instead of Riemann-Siegel Z(t) for Xi proxy", files: ["supercritical.js"], detail: "The heatEvolvedXi() function approximated Ξ(t) by taking Re(ζ(½+it)) — the real part of the raw zeta value on the critical line. But Re(ζ(½+it)) is not a real-valued function with zeros at the zeta zeros; its zero set is different from that of ζ. The correct real-valued proxy is the Riemann-Siegel Z function Z(t) = exp(iθ(t))·ζ(½+it), which is real for real t and has zeros exactly where ζ does. Replaced the zetaCriticalStrip call with the already-implemented riemannSiegelZ(t)." },
  { id: 24, timestamp: "2026-03-02T13:55:00Z", category: "accuracy", summary: "Fix Keiper-Li title and legend omitting +½ constant from asymptotic formula", files: ["LiCriterionViz.jsx"], detail: "The Keiper-Li reference curve was plotted as ½log(n/2πe) + ½ (matching the explainer text), but the chart title said 'should approach ½log(n/2πe)' and the legend label said '½log(n/2πe)' — both omitting the +½ constant term. This made users think the dashed reference curve was wrong when it actually included the correct sub-leading constant. Updated both the title and legend to show '½log(n/2πe) + ½' to match the plotted curve and the tab explainer." },
  { id: 25, timestamp: "2026-03-02T14:00:00Z", category: "ux", summary: "Add critical line color indicator to σ slider in OscillatorChainViz", files: ["OscillatorChainViz.jsx"], detail: "The σ slider in OscillatorChainViz had no visual feedback about proximity to the critical line σ = 0.5, unlike the same slider in WaveSimViz and FourierDomainViz. Added the green/yellow/red color indicator: green when σ ≈ 0.5 (within 0.02), yellow when close (within 0.15), and red when far away. Applied to the slider label, track accent color, and value display for consistency with the rest of the app." },
  { id: 26, timestamp: "2026-03-02T14:05:00Z", category: "visual", summary: "Add missing y-axis labels to both charts in Heat Flow tab", files: ["SupercriticalViz.jsx"], detail: "The Heat Flow tab in SupercriticalViz had two charts — zero positions (top) and heat-evolved Xi function (bottom) — but neither had a y-axis label. Users could see tick values (0.30–0.70 for sigma, numeric for Hτ) but couldn't tell what quantity each axis represented. Added rotated y-axis labels: 'σ = Re(ρ)' for the top zero-position chart and 'Hτ(t)' for the bottom heat-evolved Xi chart, matching the axis label style used in HamiltonianViz and ExplicitFormulaViz." },
  { id: 27, timestamp: "2026-03-02T14:10:00Z", category: "visual", summary: "Add right-side y-axis with π-labeled ticks for phase curve in Euler product plot", files: ["EulerProductViz.jsx"], detail: "The Euler product visualization plotted cumulative phase arg(ζ) as a purple curve on the same chart as magnitude, but had no secondary y-axis — users couldn't read phase values. Added a right-side y-axis with ticks at −π, −π/2, 0, π/2, π in matching purple, increased the right margin to 55px for label room, bumped phase line opacity from 0.6 to 0.7, and updated header labels to '← Cumulative |ζ|' and 'Phase arg(ζ) →' to indicate which axis belongs to which curve." },
  { id: 28, timestamp: "2026-03-02T14:15:00Z", category: "performance", summary: "Cache Borwein acceleration weights in zetaCriticalStrip to avoid recomputing per call", files: ["zeta.js"], detail: "The zetaCriticalStrip() function recomputed the Borwein acceleration weights e_k (a Float64Array of 51 binomial-coefficient-derived values) on every call, even though these weights depend only on N, not on s. The heatmap alone calls this function 10,000 times with N=50, causing 10,000 redundant weight computations (each involving 50 iterations with Math.pow calls). Extracted weight computation into a cached getBorweinWeights(n) helper with a module-level Map, so weights are computed once per distinct N value and reused on all subsequent calls." },
  { id: 29, timestamp: "2026-03-02T14:20:00Z", category: "content", summary: "Add Z(t) motivation and heatmap reading guide explainer cards to ZetaPage", files: ["ZetaPage.jsx"], detail: "The Zeta Function Landscape page had only two sentences of introduction and jumped straight from the visualization to a raw zero table with no explanatory content. Added two cards in a two-column layout: 'Why Z(t)?' explains that multiplying ζ by a phase factor produces a real-valued function whose sign changes mark zeros, making them easy to count; 'Reading the Heatmap' explains that dark regions show small |ζ|, the deepest valleys at σ=1/2 are the nontrivial zeros, and RH asserts all zeros sit on the center line." },
  { id: 30, timestamp: "2026-03-02T14:25:00Z", category: "bug", summary: "Fix GradientDescentTab not redrawing when numPrimes slider changes", files: ["TwinOscillatorSimViz.jsx"], detail: "The GradientDescentTab's useEffect that draws the initial canvas had [tValue, startSigma] as its dependency array, but the curveData callback it invokes depends on numPrimes. When the user changed the Primes slider, the effect didn't re-run, so the canvas stayed stale until tValue or startSigma changed. Added numPrimes to the dependency array so the Hamiltonian curve redraws immediately when the number of primes changes." },
  { id: 31, timestamp: "2026-03-02T14:30:00Z", category: "bug", summary: "Fix energyLandscape missing 0.5 mismatch factor and bridge coupling term", files: ["oscillators.js"], detail: "The energyLandscape() function computed energy as T + mismatch², but systemHamiltonian() computes H = T + 0.5·mismatch² + 100·(1-|χ|)². The heatmap was missing the 0.5 factor on the impedance mismatch potential and omitting the bridge unitarity penalty entirely, making the 'System Energy' heatmap show a different quantity than the actual Hamiltonian plotted in HamiltonianViz. Fixed by adding the losslessBridge computation and matching the formula to systemHamiltonian." },
  { id: 32, timestamp: "2026-03-02T14:35:00Z", category: "bug", summary: "Fix ConvergenceTab third chart clipped by insufficient SVG height (700→780)", files: ["TwinOscillatorSimViz.jsx"], detail: "The ConvergenceTab in TwinOscillatorSimViz laid out three stacked sub-charts (H(σ) curves, gradient, curvature) each 180px tall with 25px top + 35px bottom margins and 30px gaps. The total required height is 3×(25+180+35) + 2×30 = 780px, but totalHeight was set to 700 and the SVG element's height style was also 700. This clipped the bottom 80px of the third chart (curvature), hiding its x-axis labels and bottom tick marks. Fixed both values to 780." },
  { id: 33, timestamp: "2026-03-02T14:40:00Z", category: "accuracy", summary: "Fix Bode integral text conflating minimum-phase with no-RHP-poles", files: ["ControlTheoryPage.jsx"], detail: "The Bode sensitivity integral explainer said 'For minimum-phase systems (no RHP poles), it is zero.' This conflates two distinct concepts: minimum-phase refers to having no right-half-plane zeros, while the Bode integral being zero depends on having no open-loop RHP poles (stable open-loop system). Fixed by replacing 'minimum-phase systems' with 'stable open-loop systems' and clarifying that the zero integral means sensitivity reduction at some frequencies must be paid for at others." },
  { id: 34, timestamp: "2026-03-02T14:45:00Z", category: "ux", summary: "Add nearest-zero proximity indicator to t slider in HamiltonianViz", files: ["HamiltonianViz.jsx"], detail: "The t = Im(s) slider in HamiltonianViz had no indication of when the user was near a zeta zero — the parameter values where the most interesting Hamiltonian behavior occurs. Added a proximity indicator that appears when t is within 1 unit of a known zero, showing the zero's index (e.g. '≈ γ₁=14.1'). The indicator turns green when very close (within 0.3) to help users find the sweet spots." },
  { id: 35, timestamp: "2026-03-02T14:50:00Z", category: "ux", summary: "Add critical line color indicator to σ slider in EulerProductViz", files: ["EulerProductViz.jsx"], detail: "The σ slider in EulerProductViz ranged from 0.1 to 2.0 but had no visual feedback about proximity to the critical line σ = 0.5, unlike the same slider in OscillatorChainViz and FourierDomainViz. Added the green/yellow/red color indicator: green when σ ≈ 0.5 (within 0.02), yellow when close (within 0.15), and red when far away. Applied to the slider label, track accent color, and value display for consistency with the rest of the app." },
  { id: 36, timestamp: "2026-03-02T14:55:00Z", category: "ux", summary: "Add hover tooltips to all data points in LiCriterionViz (bars, scatter, heat flow)", files: ["LiCriterionViz.jsx"], detail: "The LiCriterionViz had three modes (Li Coefficients, Keiper-Li, de Bruijn-Newman) with data points rendered as bars or circles, but none provided hover feedback showing exact values. Added native SVG <title> tooltips to all interactive elements: Li bars show 'λₙ = value (zeros used)', Keiper-Li scatter dots show 'n, λₙ, λₙ/n', and de Bruijn-Newman dots show 'τ, γ, σ'. Also added crosshair cursor to signal interactivity." },
  { id: 37, timestamp: "2026-03-02T15:00:00Z", category: "ux", summary: "Add nearest-zero proximity indicator to t slider in ScatteringMatrixViz", files: ["ScatteringMatrixViz.jsx"], detail: "The t = Im(s) slider in ScatteringMatrixViz showed no indication of when the user was near a zeta zero, where the scattering matrix exhibits its most interesting behavior (|χ|=1 on the critical line, phase jumps of π). Added the same proximity indicator used in HamiltonianViz: when t is within 1 unit of a known zero, it shows the zero's index and value (e.g. '≈ γ₁=14.1'), turning green when very close (within 0.3)." },
  { id: 38, timestamp: "2026-03-02T15:05:00Z", category: "visual", summary: "Fix ExplicitFormulaViz legend to match plot styling (dashed PNT line, step-pattern staircase)", files: ["ExplicitFormulaViz.jsx"], detail: "The ExplicitFormulaViz legend showed all three entries as identical solid lines, but the actual plot uses different styles: ψ(x) is a step function (curveStepAfter), the explicit formula is a smooth curve, and the PNT approximation y=x is a dashed line (stroke-dasharray '4,4'). Replaced the uniform legend with style-matched entries: a small step pattern for ψ(x), a solid line for the explicit formula, and a dashed line for the PNT approximation, so the legend accurately represents how each curve appears in the plot." },
  { id: 39, timestamp: "2026-03-02T15:10:00Z", category: "visual", summary: "Add colorbar with labeled scale to heatmap mode in ZetaLandscapeViz", files: ["ZetaLandscapeViz.jsx"], detail: "The |ζ(σ+it)| heatmap in ZetaLandscapeViz used a four-stage colormap (dark blue → cyan → yellow → red) to represent log(1+|ζ|) values, but had no visual legend showing what colors correspond to which values. Users could see bright and dark regions but couldn't read quantitative values. Added a vertical colorbar on the right side with the exact same colormap, tick marks at integer values 0–4, and a rotated 'log(1+|ζ|)' label, drawn over a semi-transparent background for readability." },
  { id: 40, timestamp: "2026-03-02T15:15:00Z", category: "visual", summary: "Add horizontal gridlines to ExplicitFormulaViz for easier y-value reading", files: ["ExplicitFormulaViz.jsx"], detail: "The ExplicitFormulaViz chart plotted ψ(x), the explicit formula approximation, and the PNT line y=x, but had no horizontal gridlines — users could see y-axis tick marks but couldn't trace them across the plot to read values from the curves. Added dashed horizontal gridlines at each y-axis tick using D3's tickSize(-w) pattern, styled in a subtle #1e293b to match the dark theme without competing with the data lines." },
  { id: 41, timestamp: "2026-03-02T15:20:00Z", category: "accuracy", summary: "Fix BridgeTab reflection coefficient formula missing denominator (1+|χ|)", files: ["TwinOscillatorSimViz.jsx"], detail: "The BridgeTab explainer text stated the reflection coefficient as R = |1 − |χ||, but the actual computation in oscillators.js uses the standard impedance mismatch formula R = |1 − |χ|| / (1 + |χ|). The text formula gives unbounded values for large |χ| (e.g. R → ∞ as |χ| → ∞), while the code correctly normalizes to [0, 1). Updated the LaTeX in the explainer to R = |1 − |χ|| / (1 + |χ|) to match the computed quantity." },
  { id: 42, timestamp: "2026-03-02T15:25:00Z", category: "ux", summary: "Add critical line color indicator to σ slider in NyquistBodeViz", files: ["NyquistBodeViz.jsx"], detail: "The σ slider in NyquistBodeViz ranged from 0.1 to 0.9 but had no visual feedback about proximity to the critical line σ = 0.5, unlike the same slider in OscillatorChainViz, FourierDomainViz, and EulerProductViz. Added the green/yellow/red color indicator: green when σ ≈ 0.5 (within 0.02), yellow when close (within 0.15), and red when far away. Applied to the slider label, track accent color, and value display for consistency with the rest of the app." },
  { id: 43, timestamp: "2026-03-02T15:30:00Z", category: "content", summary: "Add impedance matching and observation guide explainer cards to WaveSimPage", files: ["WaveSimPage.jsx"], detail: "The WaveSimPage had only a brief tab-listing card with no explanation of the underlying physics. Added two cards in a two-column layout: 'Impedance Matching & Perfect Transmission' explains why σ=1/2 gives zero reflection (Z_dir = Z_dual from the functional equation symmetry) with the reflection coefficient formula; 'What to Look For' provides a structured guide for each regime (σ=0.5, away from 0.5, near a zero, more primes) so users know what behavior to observe in each tab." },
  { id: 44, timestamp: "2026-03-02T15:35:00Z", category: "performance", summary: "Precompute sparse non-zero entries in vonMangoldtSpectrum to avoid redundant Math.log calls", files: ["supercritical.js"], detail: "The vonMangoldtSpectrum() DFT loop iterated over all n from 2 to maxN for each frequency, checking lambda[n]===0 (most entries are zero since only prime powers have Λ(n)≠0) and recomputing Math.log(n) on every frequency. With maxN=800 and 300 frequencies, this caused ~48,000 redundant Math.log calls and ~190,000 unnecessary zero-checks. Precomputed a sparse array of {lambdaN, logN} for the ~160 non-zero entries before the frequency loop, eliminating both the redundant log calls and the branch-heavy zero-skipping." },
  { id: 45, timestamp: "2026-03-02T15:40:00Z", category: "content", summary: "Add tab-by-tab exploration guide card to FourierPage", files: ["FourierPage.jsx"], detail: "The FourierPage had conceptual explainer cards but no guidance on what to look for in each of the four visualization tabs (Von Mangoldt Spectrum, Frequency Response, Spectral Energy, Prime Harmonics). Added a full-width 'What to Explore in Each Tab' card between the visualization and the existing cards, with color-coded descriptions of what each tab shows and what behaviors to observe when adjusting parameters like maxN, σ, and number of primes." },
  { id: 46, timestamp: "2026-03-02T15:45:00Z", category: "bug", summary: "Fix frequency mode x-scale off-by-one causing last prime to render past chart edge", files: ["PrimeGapCouplingViz.jsx"], detail: "The shared x-scale in PrimeGapCouplingViz used domain [0, data.length-1] where data.length = primes.length-1 (one entry per gap). In coupling and gap modes this is correct, but frequency mode plots primes.length points (one per prime). The last prime's frequency dot, the connecting line endpoint, and the reference curve all rendered past the right chart edge because x(primes.length-1) exceeded the domain. Fixed by updating the x-scale domain to [0, primes.length-1] at the start of the frequency mode block." },
  { id: 47, timestamp: "2026-03-02T15:50:00Z", category: "bug", summary: "Fix Heat Flow evolved zeros clamped to hardcoded gamma=155 instead of dynamic xMax", files: ["SupercriticalViz.jsx"], detail: "The Heat Flow tab clamped evolved zero positions to Math.min(155, z.gamma), but the x-axis scale dynamically extends beyond 155 when numZeros exceeds ~50 (the 200th zero has gamma ≈ 682). This caused all high zeros to pile up at gamma=155 while the axis stretched to accommodate them, making the evolved dots cluster at the wrong x position. Fixed by clamping to xMax (the dynamic axis maximum) instead of the hardcoded 155." },
  { id: 48, timestamp: "2026-03-02T15:55:00Z", category: "bug", summary: "Fix ScatteringMatrixViz reflection formula missing denominator (1+|χ|) in explainer", files: ["ScatteringMatrixViz.jsx"], detail: "The reflection mode explainer in ScatteringMatrixViz stated the formula as Γ = |1 − |χ(s)||, but the actual computation in oscillators.js uses Γ = |1 − |χ|| / (1 + |χ|). The text formula gives unbounded values for large |χ| (e.g. Γ → ∞ as |χ| → ∞), while the code correctly normalizes to [0, 1). This is the same formula discrepancy that was previously fixed in TwinOscillatorSimViz's BridgeTab (improvement #41). Updated the LaTeX to Γ = |1 − |χ(s)|| / (1 + |χ(s)|) to match the computed quantity." },
  { id: 49, timestamp: "2026-03-02T16:00:00Z", category: "performance", summary: "Hoist loop-invariant density calculation out of inner pair-correlation loop in GUEStatisticsViz", files: ["GUEStatisticsViz.jsx"], detail: "In the pair-correlation mode of GUEStatisticsViz, the local density Math.log(zeros[i]/(2π))/(2π) was computed inside the inner j-loop despite depending only on the outer i-index. With 300 zeros this caused ~44,550 redundant Math.log calls (each i's density recomputed for every j > i). Hoisted the density computation to the outer loop, reducing Math.log calls from O(n²) to O(n)." },
  { id: 50, timestamp: "2026-03-02T16:05:00Z", category: "content", summary: "Add feedback loop analogy and RH interpretation intro cards to ControlTheoryPage", files: ["ControlTheoryPage.jsx"], detail: "The ControlTheoryPage jumped directly from the loop gain formula L(s) = χ(s)·ζ(1−s)/ζ(s) into the Nyquist visualization with no conceptual introduction. Added a two-column card section explaining: (1) 'The Feedback Loop Analogy' — how the functional equation factors ζ into a plant/controller/feedback channel structure where zeros become instability points, and (2) 'What This Tells Us About RH' — why σ=1/2 gives marginal stability (|χ|=1 means lossless feedback) and how zeros off the critical line would cause Nyquist encirclements of −1." },
  { id: 51, timestamp: "2026-03-02T16:10:00Z", category: "accuracy", summary: "Fix OscillatorChainViz explainer claiming L=log(p), C=1/log(p) give ω=log(p) when they give ω=1", files: ["OscillatorChainViz.jsx"], detail: "The oscillator chain explainer text stated each prime contributes 'resonant frequency ω_p = log p, inductance L_p = log p, and capacitance C_p = 1/log p.' But 1/√(LC) = 1/√(log(p)·(1/log(p))) = 1, not log(p) — a direct mathematical contradiction. The code comment in oscillators.js already correctly noted ω₀ = 1. Replaced the contradictory L/C claims with the correct statement: natural frequency ω_p = log p (from p^{-s} = e^{-s log p}) and characteristic impedance Z_p = log p, which is the quantity that matters for the impedance-matching interpretation at σ = 1/2." },
  { id: 52, timestamp: "2026-03-02T16:15:00Z", category: "bug", summary: "Fix pair correlation using linear density approximation instead of exact Weyl-law unfolding", files: ["GUEStatisticsViz.jsx"], detail: "The pair-correlation mode in GUEStatisticsViz unfolded zero separations using a linear approximation: (γ_j − γ_i) × density(γ_i), where density = log(γ_i/2π)/(2π). This approximates N(γ_j) − N(γ_i) by linearizing the counting function at γ_i, which can underestimate unfolded separations by up to 2× for distant pairs (e.g. γ₁=14.1 to γ₁₃=40.9 gives 3.5 vs true 6.1). Replaced with the exact Weyl-law formula N̂(γ) = (γ/2π)log(γ/2πe) + 7/8, matching the number-variance tab which already used the correct formula." },
  { id: 53, timestamp: "2026-03-02T16:20:00Z", category: "bug", summary: "Fix ThermodynamicsTab 4th chart (Specific Heat) clipped by insufficient SVG height (680→800)", files: ["SupercriticalViz.jsx"], detail: "The ThermodynamicsTab in SupercriticalViz stacks 4 charts vertically (Free Energy, Entropy, Pressure, Specific Heat), each occupying chartH=130 plus margins and a 22px gap. The 4th chart (qi=3) starts at yOff=612 and extends to y≈794, but the SVG totalHeight was set to 680 — clipping ~114px off the bottom of the Specific Heat chart, hiding its x-axis labels and lower data. Increased both the viewBox totalHeight and the JSX style height from 680 to 800 to fully contain all four charts." },
  { id: 54, timestamp: "2026-03-02T16:25:00Z", category: "visual", summary: "Add x-axis tick marks and labels to AnimatedModesViz log-space waveform display", files: ["AnimatedModesViz.jsx"], detail: "The AnimatedModesViz canvas plotted prime oscillator waveforms over a log-space domain (log x from 1 to 6) but had no x-axis tick marks, labels, or axis title. Users couldn't tell what the horizontal scale represented or read values from the waveforms. Added a bottom x-axis line with tick marks at log x = 1 through 6, numeric labels below each tick, and a 'log x' axis title in the left margin. Moved the time indicator from the bottom-right (where it overlapped the new axis) to the top-right corner." },
  { id: 55, timestamp: "2026-03-02T16:30:00Z", category: "ux", summary: "Add nearest-zero proximity indicator to t slider in ThermodynamicsTab", files: ["SupercriticalViz.jsx"], detail: "The t = Im(s) slider in the Thermodynamics tab of SupercriticalViz showed no indication of when the user was near a zeta zero, where thermodynamic quantities exhibit singularity-like behavior (free energy diverges, entropy peaks, specific heat spikes). Added the same proximity indicator used in HamiltonianViz and ScatteringMatrixViz: when t is within 1 unit of a known zero, it shows the zero's index and value (e.g. '≈ γ₁=14.1'), turning green when very close (within 0.3)." },
  { id: 56, timestamp: "2026-03-02T16:35:00Z", category: "performance", summary: "Memoize PerPrimeTab stat grid to avoid redundant oscillatorStage calls on re-render", files: ["TwinOscillatorSimViz.jsx"], detail: "The PerPrimeTab stat grid computed per-prime energy minima (101 × numPrimes × 2 oscillatorStage calls) directly in the render body with no memoization. Every React re-render — including window resize events and unrelated state changes — triggered this expensive scan. Wrapped the computation in useMemo with [tValue, numPrimes] dependencies so it only recomputes when slider values actually change." },
  { id: 57, timestamp: "2026-03-02T16:40:00Z", category: "performance", summary: "Replace O(n) repeated complex multiplication with O(1) De Moivre in LiCriterionViz", files: ["LiCriterionViz.jsx"], detail: "Both the Li Coefficients and Keiper-Li modes computed (base)^n via O(n) repeated complex multiplication inside a triple nested loop (n up to 40 × zeros up to 200 × k up to n), totaling ~320,000 complex multiplications per draw. Replaced with De Moivre's theorem: precompute polar form (r, θ) for each zero once, then compute r^n·cos(nθ) in O(1) per power. Also hoisted base calculations out of the n-loop since they depend only on the zero. Reduces complexity from O(maxN² × numZeros) to O(maxN × numZeros), a ~20× speedup." },
  { id: 58, timestamp: "2026-03-02T16:45:00Z", category: "content", summary: "Add research area guide cards to LiteraturePage explaining spectral and engineering threads", files: ["LiteraturePage.jsx"], detail: "The LiteraturePage had 14 category filters but no conceptual context explaining how the research areas relate to each other or to the prime oscillator model. Added a two-column card section between the filter bar and the reference grid: 'The Spectral Thread' explains the Hilbert-Pólya → RMT → trace formula line of research; 'The Engineering Thread' explains the circuit theory → control theory → signal processing line. Each card lists which categories it covers, helping users navigate the bibliography thematically." },
  { id: 59, timestamp: "2026-03-02T16:50:00Z", category: "accuracy", summary: "Fix pair correlation histogram normalization to match R₂ scale instead of probability density", files: ["GUEStatisticsViz.jsx"], detail: "The pair correlation histogram was normalized by dividing each bin by (total_pairs_in_range × binWidth), which produces a probability density integrating to 1 over [0, maxR]. But the overlaid GUE curve is R₂(r) = 1 − (sin πr / πr)² which approaches 1 for large r. The correct normalization divides by (N × binWidth) where N is the number of zeros, since each zero contributes R₂(r)·dr expected neighbors at distance r. The old normalization made histogram bars ~3.5× too short to match the theoretical curve." },
  { id: 60, timestamp: "2026-03-02T16:55:00Z", category: "bug", summary: "Fix pair correlation missing factor of 2 for unordered-to-ordered pair count conversion", files: ["GUEStatisticsViz.jsx"], detail: "The pair correlation R₂(r) normalization divided by N × binW, but the histogram only counts unordered pairs (i < j), while R₂ is defined via ordered pairs: each zero contributes R₂(r)·dr neighbors, giving N × R₂(r) × dr total ordered pairs. Since unordered pairs = ordered pairs / 2, the correct formula is R₂ = 2 × count / (N × binW). The missing factor of 2 caused the histogram to plateau at ~0.5 instead of ~1.0 for large separations, making it systematically below the GUE prediction curve." },
  { id: 61, timestamp: "2026-03-02T17:00:00Z", category: "bug", summary: "Fix group delay computation missing phase unwrapping at ±π atan2 boundary", files: ["WaveSimViz.jsx"], detail: "The PhaseDelayTab computed group delay via a central-difference derivative of atan2 phase values: τ = -(φ(t+δ) − φ(t−δ)) / 2δ. But atan2 wraps at ±π, so when the phase crosses this boundary between the two sample points, the difference jumps by ±2π, producing a delay error of ±2π/0.002 ≈ ±3141 — orders of magnitude off. Added a phase-unwrapping helper that normalizes the difference into [−π, π] before dividing by 2δ, giving correct group delay values for all primes and parameter settings." },
  { id: 62, timestamp: "2026-03-02T17:05:00Z", category: "ux", summary: "Add nearest-zero proximity indicator to all t sliders in TwinOscillatorSimViz", files: ["TwinOscillatorSimViz.jsx"], detail: "The four t = Im(s) sliders in TwinOscillatorSimViz (Per-Prime Energy, Gradient Descent, Convergence, Bridge Unitarity) showed no indication of proximity to zeta zeros, where the Hamiltonian exhibits its most interesting behavior (energy minima sharpen, gradient descent converges faster, bridge becomes unitary). Added the same proximity indicator used in HamiltonianViz and ScatteringMatrixViz: when t is within 1 unit of a known zero, it shows the zero's index and value (e.g. '≈ γ₁=14.1'), turning green when very close (within 0.3)." },
  { id: 63, timestamp: "2026-03-02T17:10:00Z", category: "visual", summary: "Add horizontal gridlines to HamiltonianViz for easier energy value reading", files: ["HamiltonianViz.jsx"], detail: "The Hamiltonian energy scan chart plotted four energy components (total, kinetic, mismatch, bridge) but had no horizontal gridlines — users could see y-axis tick marks but couldn't trace them across the plot to read values from the curves. Added dashed horizontal gridlines at each y-axis tick using D3's tickSize(-w) pattern, styled in a subtle #1e293b to match the dark theme without competing with the data lines." },
  { id: 64, timestamp: "2026-03-02T17:15:00Z", category: "performance", summary: "Pre-compute 256-entry colormap palette to eliminate per-pixel interpolation in ZetaLandscapeViz heatmap", files: ["ZetaLandscapeViz.jsx"], detail: "The heatmap inner loop (100×100 = 10,000 iterations) and colorbar loop (~300 iterations) both repeated a 4-branch color interpolation with 3 arithmetic operations per branch plus an rgb() string concatenation on every iteration. Replaced with a module-level pre-computed 256-entry palette array, so each pixel now does a single array index lookup instead of branching + interpolation + string formatting. Eliminates ~10,300 string allocations and ~30,900 arithmetic operations per draw." },
  { id: 65, timestamp: "2026-03-02T17:20:00Z", category: "performance", summary: "Memoize hamiltonianSigmaScan to avoid recomputing on window resize", files: ["HamiltonianViz.jsx"], detail: "The hamiltonianSigmaScan() call (60 steps × systemHamiltonian per step, each computing oscillator energies for numPrimes primes) was inside the draw() useCallback, which re-ran on every window resize event. Since the scan depends only on tValue and numPrimes — not viewport dimensions — extracted it into a useMemo([tValue, numPrimes]) so resize events only redraw the SVG with cached data instead of recomputing ~60 Hamiltonian evaluations." },
  { id: 66, timestamp: "2026-03-02T17:25:00Z", category: "performance", summary: "Avoid per-frame canvas buffer reallocation in AnimatedModesViz animation loop", files: ["AnimatedModesViz.jsx"], detail: "The draw() function unconditionally set canvas.width and canvas.height on every animation frame (60fps), forcing the browser to deallocate the pixel buffer, reallocate it, and clear it — even when the canvas size hadn't changed. Also replaced ctx.scale() (which accumulates transforms) with ctx.setTransform() (which resets to an absolute matrix). Now the buffer is only reallocated when the canvas actually resizes, eliminating ~59 unnecessary buffer deallocate/reallocate cycles per second during animation." },
  { id: 67, timestamp: "2026-03-02T17:30:00Z", category: "content", summary: "Add de Bruijn-Newman constant exploration entry explaining heat flow and oscillator chain dissipation", files: ["explorations.js"], detail: "Added exploration exp-026 'The de Bruijn-Newman Constant: Heat Flow in the Oscillator Chain'. The app had a Heat Flow visualization tab in SupercriticalViz but no exploration entry explaining the mathematical foundations: the heat-evolved xi function H_τ(z), the constant Λ as the threshold where zeros become real, the equivalence RH ⟺ Λ ≤ 0, and the circuit interpretation of τ as uniform dissipation added to the oscillator chain. The entry covers de Bruijn (1950), Newman (1976), Rodgers-Tao (2020), and Polymath 15 (2019) with six insights and connections to the existing visualization." },
  { id: 68, timestamp: "2026-03-02T17:35:00Z", category: "bug", summary: "Fix signal flow legend showing amplitude ratio instead of power fraction for transmitted/reflected percentages", files: ["WaveSimViz.jsx"], detail: "The Signal Flow tab's legend displayed 'Transmitted' and 'Reflected' percentages using the amplitude reflection coefficient Γ directly (T=1−Γ, R=Γ), but Γ = |1−|χ||/(1+|χ|) is an amplitude ratio, not a power fraction. This caused the reflected percentage to be dramatically overstated — e.g. showing 'Reflected: 33%' when only Γ²=11% of power was actually reflected. Fixed the legend to display power fractions (1−Γ² and Γ²) which correctly sum to 100% and represent physical energy conservation. Also fixed the amplitude transmission coefficient from the incorrect 1−Γ to the correct √(1−Γ²), which controls the visual brightness of transmitted signal arrows." },
  { id: 69, timestamp: "2026-03-02T17:40:00Z", category: "bug", summary: "Fix swapped |χ| region annotations in ScatteringMatrixViz magnitude mode", files: ["ScatteringMatrixViz.jsx"], detail: "The magnitude mode in ScatteringMatrixViz had its region annotations placed in the wrong halves of the plot. At σ = 0.25 (left of critical line) it displayed '|χ| < 1: absorptive' in blue, while at σ = 0.75 (right) it displayed '|χ| > 1: amplifying' in red. The physics is reversed: for σ < 0.5 the bridge amplifies (|χ| > 1) and for σ > 0.5 it attenuates (|χ| < 1), as correctly stated in the tab explainer text. Swapped both the label text and colors so the left region shows '|χ| > 1: amplifying' in red and the right shows '|χ| < 1: attenuating' in blue." },
  { id: 70, timestamp: "2026-03-03T00:00:00Z", category: "accuracy", summary: "Fix wrong sign in entropy formula: S = log|ζ| − σ·∂log|ζ|/∂σ, not plus", files: ["supercritical.js"], detail: "The primon gas entropy computation used S = log|ζ| + σ·∂(log|ζ|)/∂σ, but the correct thermodynamic identity is S = -∂F/∂T = log Z - β·∂(log Z)/∂β where β = σ = 1/T. Since dF/dT = -log Z + β·∂(log Z)/∂β, the entropy has a minus sign on the second term: S = log|ζ| - σ·∂(log|ζ|)/∂σ. The wrong sign caused the entropy to be systematically too small (or even negative) in the supercritical region where ∂(log|ζ|)/∂σ < 0, producing an unphysical thermodynamic portrait." },
  { id: 71, timestamp: "2026-03-03T06:00:00Z", category: "ux", summary: "Show metric value in Energy Landscape hover tooltip alongside σ and t coordinates", files: ["EnergyLandscapeViz.jsx"], detail: "The Energy Landscape heatmap's hover tooltip only showed the σ and t coordinates of the cursor position, but not the actual metric value at that point. Users hovering to read specific values from the heatmap had to mentally map colors to the colorbar. Added nearest-grid-point value lookup to the hover handler, displaying the metric value (H, |Z₁−Z₂|, |ζ(s)|, or |ζ(1−s)| depending on mode) in amber next to the coordinates." },
  { id: 72, timestamp: "2026-03-03T12:00:00Z", category: "accuracy", summary: "Fix bridge scattering matrix using ξ(s) (completed zeta) instead of proper transmission coefficient τ", files: ["OscillatorsPage.jsx"], detail: "The bridge scattering matrix formula used ξ(s) and ξ(1-s) as off-diagonal (transmission) entries, but ξ is the completed zeta function which vanishes at zeta zeros. At a zero on the critical line where Γ=0 and ξ=0, the matrix becomes S=0, violating unitarity S†S=I. Replaced with the correct scattering parameters: reflection Γ=|1-|χ||/(1+|χ|) and transmission τ=√(1-Γ²), which properly satisfy |Γ|²+|τ|²=1 and give S†S=I on the critical line." },
  { id: 73, timestamp: "2026-03-03T12:05:00Z", category: "visual", summary: "Add right-side y-axis for mismatch curve in Spectral Energy tab of FourierDomainViz", files: ["FourierDomainViz.jsx"], detail: "The Spectral Energy tab plotted the Mismatch curve (red dashed) on a secondary y-scale (y2) but had no right-side axis drawn — viewers had no way to read mismatch values and would assume the curve shared the left-side energy scale, leading to misinterpretation. Added a right-side y-axis with red tick labels matching the mismatch curve color and a rotated 'Mismatch |E_dir − E_dual|' label, making both scales independently readable." },
  { id: 74, timestamp: "2026-03-03T18:00:00Z", category: "performance", summary: "Memoize bridge data array in ScatteringMatrixViz to avoid recomputing on mode switch or resize", files: ["ScatteringMatrixViz.jsx"], detail: "The ScatteringMatrixViz computed 101 losslessBridge() calls (each involving cPow, lanczosGamma, and multiple complex multiplications) inside the drawMagnitude callback, which re-ran on every mode switch and window resize even though the data depends only on tValue. Extracted the data array into a useMemo([tValue]) so switching between magnitude/reflection/phase modes and resizing the window now reuse cached bridge data instead of recomputing ~101 expensive complex-arithmetic operations." },
  { id: 75, timestamp: "2026-03-03T18:30:00Z", category: "content", summary: "Add Hilbert-Pólya conjecture exploration entry connecting spectral theory to oscillator model", files: ["explorations.js"], detail: "Added exploration exp-027 'The Hilbert-Pólya Conjecture: Spectral Origin of the Zeros'. The app's Hamiltonian and PT-symmetry explorations referenced this conjecture but no entry explained it directly. The new entry covers the historical thread (Pólya's letter, Montgomery-Odlyzko GUE statistics, Berry-Keating H=xp, Connes' absorption spectrum), explains how the oscillator chain Hamiltonian is a finite-dimensional pedagogical analog, and connects PT-symmetry of the functional equation to the self-adjointness requirement." },
  { id: 76, timestamp: "2026-03-03T19:00:00Z", category: "bug", summary: "Fix stale hardcoded Pages (9→15) and Visualizations (14→17) counts on HomePage", files: ["HomePage.jsx"], detail: "The HomePage stat grid hardcoded '9 Pages' and '14 Visualizations', but the app now has 15 routes (pages) and 17 visualization components (*Viz*.jsx files). These counts went stale as new pages (Simulator, Fourier, Supercritical, Docs, Waves, Improvements) and visualizations (WaveSimViz, FourierDomainViz, ScatteringMatrixViz) were added. Updated both to their correct current values." },
  { id: 77, timestamp: "2026-03-04T00:00:00Z", category: "bug", summary: "Fix Spectral Energy right y-axis label showing |E_dir − E_dual| instead of |Z_dir − Z_dual|", files: ["FourierDomainViz.jsx"], detail: "The Spectral Energy tab's right y-axis label said 'Mismatch |E_dir − E_dual|' (energy difference), but the plotted curve actually shows impedance mismatch cAbs(cSub(direct.totalImpedance, dual.totalImpedance)) = |Z_dir − Z_dual|. The 'E' notation would suggest energy difference (which vanishes at σ=0.5 due to |ζ(s)|=|ζ(s̄)|), while the impedance mismatch generally does not vanish there. Changed the label to 'Mismatch |Z_dir − Z_dual|' to accurately describe the plotted quantity." },
  { id: 78, timestamp: "2026-03-04T06:00:00Z", category: "performance", summary: "Eliminate redundant zetaExtended calls in thermodynamicState specific heat computation", files: ["supercritical.js"], detail: "The thermodynamicState function computed zetaExtended(σ±ds, t) twice — once for the entropy first derivative and again identically as zPP/zMM for the specific heat second derivative. Each zetaExtended call involves Borwein-accelerated eta summation (~50 complex exponentials). Removed the duplicate calls and cached log-magnitude values, saving 2 expensive zeta evaluations per call. Since thermodynamicScan invokes this in a 100-iteration loop, this eliminates ~200 redundant zeta computations per scan." },
  { id: 79, timestamp: "2026-03-04T06:00:00Z", category: "bug", summary: "Fix heatEvolvedXi applying Gaussian smoothing for negative τ (backward heat flow) instead of returning unsmoothed Z(t)", files: ["supercritical.js"], detail: "The heatEvolvedXi function computed Gaussian convolution for all τ values, including τ < 0 (backward heat flow). This produced smoothed/blurred Xi for negative τ, when the physics says cooling should sharpen the function (zeros stay on the critical line). The code even had an unused 'sign' variable indicating the τ < 0 case was meant to be handled differently. Fixed by returning riemannSiegelZ(t) directly for τ ≤ 0, consistent with the Rodgers-Tao theorem (Λ ≥ 0) and the heatFlowZeros function which correctly keeps zeros at σ = 0.5 for non-positive τ." },
  { id: 80, timestamp: "2026-03-03T18:00:00Z", category: "content", summary: "Add Mertens function exploration entry on inverse cascade and constructive interference of zero modes", files: ["explorations.js"], detail: "Added exploration exp-028 'The Mertens Function: Inverse Cascade and Constructive Interference'. The app covered the direct cascade (ζ via Euler product) and its impulse response (explicit formula for ψ(x)), but not the inverse cascade 1/ζ(s) = Π(1−p^{−s}). The new entry explains that 1/ζ is a notch-filter bank (admittance of the cascade), its summatory function M(x) has the same zeta-zero modes but with weights 1/(ρζ'(ρ)), and the disproved Mertens conjecture shows these modes can constructively interfere beyond √x — a key cautionary counterpoint to the oscillator model's 'RH looks natural' narrative." },
  { id: 81, timestamp: "2026-03-03T19:00:00Z", category: "bug", summary: "Fix StatisticsPage Keiper-Li description omitting +½ constant from asymptotic formula", files: ["StatisticsPage.jsx"], detail: "The StatisticsPage description of the Keiper-Li asymptotic showed λₙ/n → ½log(n/2πe) but was missing the +½ additive constant. The correct formula is λₙ/n → ½log(n/2πe) + ½. This same error had been fixed in LiCriterionViz.jsx (improvement #24) but the StatisticsPage subtitle text still had the incomplete formula. Fixed to match the correct asymptotic shown in the visualization and its legend." },
  { id: 82, timestamp: "2026-03-03T20:00:00Z", category: "ux", summary: "Add expand/collapse chevron indicator to exploration entries", files: ["ExplorationsPage.jsx"], detail: "Exploration entries on the ExplorationsPage were clickable to expand/collapse, but the only visual indicator was a small 'Click to expand' text at the bottom of collapsed entries. Added a rotating chevron (▶) next to each entry title that points right when collapsed and rotates 90° downward when expanded, with a smooth CSS transition. This provides an immediate visual affordance that entries are interactive, following standard disclosure widget conventions. Removed the now-redundant 'Click to expand' hint text." },
  { id: 83, timestamp: "2026-03-03T21:00:00Z", category: "ux", summary: "Add hover-to-inspect hint text on Energy Landscape heatmap when not hovering", files: ["EnergyLandscapeViz.jsx"], detail: "The Energy Landscape heatmap canvas supports hover-to-inspect (crosshair cursor + coordinate/value readout), but users had no way to discover this feature. The readout area was completely empty when not hovering, and the only visual cue was the subtle crosshair cursor. Added an italic hint 'Hover over heatmap to inspect values' that appears in the controls bar when not hovering and is replaced by the actual readout once the user moves their mouse over the canvas." },
  { id: 84, timestamp: "2026-03-03T22:00:00Z", category: "visual", summary: "Add shaded area between PNT line and spectral approximation in ExplicitFormulaViz", files: ["ExplicitFormulaViz.jsx"], detail: "The ExplicitFormulaViz shows the PNT approximation ψ(x) ≈ x (gray dashed) and the spectral reconstruction x − Σ x^ρ/ρ (gold), but the correction contributed by zeta zeros was not visually highlighted. Added a semi-transparent gold shaded region between the two curves, making the spectral correction visible at a glance. The shaded area shrinks as more zeros are added, directly illustrating how the explicit formula converges." },
  { id: 85, timestamp: "2026-03-03T23:00:00Z", category: "visual", summary: "Add missing y-axis labels to all three modes in PrimeGapCouplingViz", files: ["PrimeGapCouplingViz.jsx"], detail: "The PrimeGapCouplingViz has three display modes (Coupling Strength, Prime Gaps, Oscillator Frequencies) but none of them had a y-axis label — only the shared x-axis label 'Prime index n' was present. Added mode-specific rotated y-axis labels: 'Coupling Y' for coupling mode, 'Gap size' for gap mode, and 'Frequency ω' for frequency mode. This makes the plotted quantity immediately clear without relying solely on the chart title." },
  { id: 86, timestamp: "2026-03-03T23:30:00Z", category: "performance", summary: "Derive negative frequency Nyquist contour via Schwarz reflection instead of recomputing 301 zeta evaluations", files: ["NyquistBodeViz.jsx"], detail: "The drawNyquist function computed the negative frequency contour by calling computeLoopGain 301 times, each involving 2 Borwein-accelerated zetaCriticalStrip calls plus a losslessBridge call. By the Schwarz reflection principle, L(σ−it) = conj(L(σ+it)), so the negative contour's real parts are identical and imaginary parts are negated. Replaced the expensive loop with a single .map() that conjugates the already-computed positive frequency points, eliminating ~602 zeta evaluations per Nyquist redraw." },
  { id: 87, timestamp: "2026-03-03T23:45:00Z", category: "content", summary: "Add tab-by-tab exploration guide card to SupercriticalPage", files: ["SupercriticalPage.jsx"], detail: "The SupercriticalPage had four visualization tabs (Extended Landscape, Thermodynamics, Heat Flow, Euler Product Phase) but no guide explaining what each tab shows or what to look for. Added a 'What to Explore in Each Tab' card between the visualization and the existing explainer cards. Each tab gets a color-coded description: the landscape tab highlights the pole and functional equation symmetry, thermodynamics points out the Bost-Connes divergence, heat flow explains the zero migration under τ, and Euler product phase describes prime phase cancellation near zeros." },
  { id: 88, timestamp: "2026-03-03T12:00:00Z", category: "accuracy", summary: "Fix wrong claim that Euler product gain diverges at zeta zeros", files: ["FourierDomainViz.jsx"], detail: "The Frequency Response tab explainer incorrectly stated 'At zeta zeros, the transfer function has singularities — the gain diverges.' This is wrong: ζ(s) has zeros (not poles) at nontrivial zeros, so |ζ(ρ)| = 0 (gain vanishes, not diverges). Moreover, the Euler product only converges for σ > 1, where ζ has no zeros at all. The peaks visible in the Bode plot are resonance-like artifacts of constructive phase alignment in the divergent partial product, not singularities. Replaced with an accurate description of what the peaks represent." },
  { id: 89, timestamp: "2026-03-04T00:00:00Z", category: "bug", summary: "Fix Extended Landscape explainer claiming bottom panel is a 2D heatmap when it shows a 1D phase curve", files: ["SupercriticalViz.jsx"], detail: "The ExtendedLandscapeTab explainer text said 'the bottom shows the 2D heatmap with phase coloring' but the bottom panel actually renders a 1D arg ζ(σ+it) phase curve plotted against σ. There is no 2D heatmap in this tab — the imported zetaLandscapeExtended function was never used. Fixed the description to accurately say the bottom shows arg ζ (the phase/argument) across the same σ range, and removed the unused zetaLandscapeExtended import." },
  { id: 90, timestamp: "2026-03-03T22:00:00Z", category: "ux", summary: "Add hover tooltips to Euler product factor bars and cumulative magnitude dots", files: ["EulerProductViz.jsx"], detail: "The EulerProductViz showed individual Euler factor bars and cumulative magnitude dots for each prime, but neither had hover tooltips — users could not inspect the exact values. Added SVG title elements to both: factor bars show the prime, individual factor magnitude |1−p⁻ˢ|⁻¹, and cumulative |ζ|; cumulative dots show the prime, cumulative |ζ|, and phase in degrees. Also added crosshair cursor to indicate interactivity." },
  { id: 91, timestamp: "2026-03-03T19:30:00Z", category: "ux", summary: "Show highest zero frequency (γ_max) next to Zeta Zeros Used slider in ExplicitFormulaViz", files: ["ExplicitFormulaViz.jsx"], detail: "The ExplicitFormulaViz 'Zeta Zeros Used' slider showed only the count of zeros (e.g., 20) but gave no indication of what frequency band they cover. Users had to know the zero table by heart to understand their spectral resolution. Added a γ_max annotation next to the count that displays the imaginary part of the highest zero being used (e.g., '(γ_max ≈ 77.1)'), making it immediately clear how much of the zero spectrum the reconstruction includes." },
  { id: 92, timestamp: "2026-03-04T06:30:00Z", category: "visual", summary: "Fix GUE legend swatches showing lines for histogram data in spacing and pair-correlation modes", files: ["GUEStatisticsViz.jsx"], detail: "In the spacing distribution and pair-correlation modes of GUEStatisticsViz, the legend entry for 'Zeta zeros' drew a solid line swatch, but the actual chart data is rendered as filled histogram bars. This visual mismatch made the legend misleading — users would look for a line in the chart that doesn't exist. Replaced the line swatch with a small filled rectangle matching the histogram bar styling (blue fill with blue stroke for spacing mode, purple fill with purple stroke for pair-correlation mode). The GUE/GOE/Poisson curve entries remain as line swatches since they correctly represent smooth curves." },
  { id: 93, timestamp: "2026-03-04T07:00:00Z", category: "visual", summary: "Add missing y-axis labels to all three modes in GUEStatisticsViz", files: ["GUEStatisticsViz.jsx"], detail: "All three modes of GUEStatisticsViz (spacing distribution, pair correlation, number variance) had x-axis labels but no y-axis labels, making it unclear what quantity is plotted vertically. Added rotated y-axis labels: 'P(s)' for the spacing distribution (probability density), 'R₂(x)' for pair correlation, and 'Σ²(L)' for number variance. These match the standard notation used in the chart titles and explainer text." },
  { id: 94, timestamp: "2026-03-03T07:30:00Z", category: "accuracy", summary: "Fix kinetic energy formula using H_p* (conjugate) instead of H_p(1-s) (dual) in HamiltonianViz", files: ["HamiltonianViz.jsx"], detail: "The Hamiltonian explainer displayed the kinetic energy formula as T = Σ_p ½ log p (|H_p|² + |H_p*|²), where H_p* denotes the complex conjugate. Since |H̄_p(s)|² = |H_p(s)|², this would trivially equal 2Σ_p ½ log p |H_p|², which is not what the code computes. The actual computation evaluates both the direct ladder at s and the dual ladder at 1−s (via dualLadder which sets sDual = [1−σ, −t]), giving T = Σ_p ½ log p (|H_p(s)|² + |H_p(1−s)|²). Fixed the LaTeX to show the correct dual argument." },
  { id: 95, timestamp: "2026-03-03T08:00:00Z", category: "ux", summary: "Add nearest-zero proximity indicator to t slider in WaveSimViz", files: ["WaveSimViz.jsx"], detail: "The WaveSimViz t (Im(s)) slider showed only the numeric value but gave no indication of proximity to zeta zeros. Since the wave simulation behavior changes dramatically near zeros (bridge becomes lossless, impedance matches), knowing the nearest zero is essential for exploration. Added a nearest-zero indicator that appears when t is within 1 unit of a zero, showing the zero's index and value (e.g., '≈ γ₁=14.1'), turning green when within 0.3 units. Matches the pattern already used in HamiltonianViz, ScatteringMatrixViz, SupercriticalViz, and TwinOscillatorSimViz." },
  { id: 96, timestamp: "2026-03-03T18:30:00Z", category: "bug", summary: "Fix Euler factor bar heights using y-scale instead of fixed linear formula in EulerProductViz", files: ["EulerProductViz.jsx"], detail: "The individual Euler factor bars in EulerProductViz used a fixed formula `Math.abs(factorMag - 1) * h * 2` for their pixel height, which was completely disconnected from the y-axis scale. This meant a factor of 1.5 could produce a bar spanning nearly the full chart height even when the y-axis range went up to 10+, causing bars to overflow far past their intended y(1)-to-y(factorMag) bounds. Replaced with `Math.abs(yMag(1) - yMag(factorMag))` so bars correctly reflect the actual y-axis scale and extend only between the |H|=1 reference line and the factor's true magnitude." },
  { id: 97, timestamp: "2026-03-03T20:00:00Z", category: "accuracy", summary: "Fix explainer wrongly claiming prime superposition is the ρ-th term of the explicit formula", files: ["AnimatedModesViz.jsx"], detail: "The AnimatedModesViz explainer stated 'The bottom row superposes all prime contributions: this is the ρ-th term in the explicit formula.' This is mathematically wrong — the ρ-th term in the explicit formula for ψ(x) is -x^ρ/ρ, a single oscillation in log-space with no per-prime decomposition. The bottom row actually shows the collective prime oscillator chain response when driven at frequency γ_n, which is a ZPO model concept. Fixed the text to describe the superposition correctly and added a parenthetical clarifying what the actual explicit formula per-zero term is." },
  { id: 98, timestamp: "2026-03-03T21:00:00Z", category: "ux", summary: "Add nearest-zero proximity indicator to t slider in OscillatorChainViz", files: ["OscillatorChainViz.jsx"], detail: "The OscillatorChainViz t (Im(s)) slider showed only the numeric value but gave no indication of proximity to zeta zeros. Since the oscillator chain behavior changes dramatically near zeros (bridge becomes lossless at σ=½, impedance matches), knowing the nearest zero is essential for exploration. Added a nearest-zero indicator that appears when t is within 1 unit of a zero, showing the zero's index and value (e.g., '≈ γ₁=14.1'), turning green when within 0.3 units. Matches the pattern already used in HamiltonianViz, ScatteringMatrixViz, WaveSimViz, SupercriticalViz, and TwinOscillatorSimViz." },
  { id: 99, timestamp: "2026-03-03T21:30:00Z", category: "visual", summary: "Add axis tick marks and labels to ZetaLandscapeViz heatmap mode", files: ["ZetaLandscapeViz.jsx"], detail: "The ZetaLandscapeViz heatmap mode displayed σ and t ranges only as plain text ('σ: 0.05 → 0.95', 't: 0 → 50') with no axis tick marks on the canvas edges, making it impossible to precisely locate features. Added labeled tick marks along the bottom edge for σ (at 0.1 intervals) and along the left edge for t (at adaptive intervals based on range), plus rotated axis labels ('σ' and 't = Im(s)'). The range text was consolidated into the title area to avoid duplication." },
  { id: 100, timestamp: "2026-03-03T22:00:00Z", category: "performance", summary: "Precompute cumulative ψ(x) table to avoid redundant vonMangoldt summation in ExplicitFormulaViz", files: ["ExplicitFormulaViz.jsx"], detail: "ExplicitFormulaViz called chebyshevPsi(x) independently for each of the 200 sample points. Since chebyshevPsi restarts its summation from n=2 every time, this resulted in O(steps × maxX) vonMangoldt evaluations — roughly 100,000 calls at maxX=500. Replaced with a single-pass precomputed cumulative table: compute vonMangoldt(n) once per n and accumulate into a Float64Array, then look up values by index. This reduces total vonMangoldt calls to O(maxX), a ~200× improvement." },
  { id: 101, timestamp: "2026-03-03T22:30:00Z", category: "bug", summary: "Remove non-functional Primes slider from NyquistBodeViz", files: ["NyquistBodeViz.jsx"], detail: "The NyquistBodeViz had a 'Primes' slider (numPrimes state, range 4–50) that appeared to control the number of primes used in the loop gain computation. However, computeLoopGain() used zetaCriticalStrip (Borwein acceleration) and losslessBridge — neither of which depends on the number of primes. The nPrimes parameter was accepted but never referenced, so the slider triggered re-renders with identical results. Removed the dead numPrimes state, the unused parameter, and the misleading slider control." },
  { id: 102, timestamp: "2026-03-03T23:00:00Z", category: "content", summary: "Add tab-by-tab exploration guide card to StatisticsPage", files: ["StatisticsPage.jsx"], detail: "The StatisticsPage had six visualization modes across two components (GUE spacing/pair-correlation/number-variance and Li/Keiper-Li/de Bruijn-Newman) but no guide explaining what each mode shows or what to look for. Added a 'What to Explore in Each Tab' card between the two visualizations. Each mode gets a color-coded description: spacing highlights level repulsion vs Poisson, pair correlation points out the Montgomery dip, number variance explains spectral rigidity, Li coefficients note the non-negativity condition, Keiper-Li shows asymptotic convergence, and de Bruijn-Newman describes the heat flow zero migration." },
  { id: 103, timestamp: "2026-03-03T23:30:00Z", category: "bug", summary: "Fix DocsPage Hamiltonian formula using H_p* (conjugate) instead of H_p(1-s) (dual)", files: ["DocsPage.jsx"], detail: "The DocsPage Hamiltonian formula displayed the kinetic energy as T = Σ_p ½ log p (|H_p|² + |H_p*|²), where H_p* denotes the complex conjugate. Since |H̄_p(s)|² = |H_p(s)|², this would trivially equal 2Σ_p ½ log p |H_p|², which is not what the code computes. The actual computation evaluates both the direct ladder at s and the dual ladder at 1−s, giving T = Σ_p ½ log p (|H_p(s)|² + |H_p(1−s)|²). This is the same bug that was fixed in HamiltonianViz (improvement #94) but persisted in the DocsPage. Fixed the LaTeX to show the correct dual argument." },
  { id: 104, timestamp: "2026-03-04T00:00:00Z", category: "bug", summary: "Fix vonMangoldtSpectrum missing primes >541 due to wrong loop break and missing prime fallback", files: ["supercritical.js"], detail: "The vonMangoldtSpectrum function in supercritical.js had an inline von Mangoldt computation that used `if (p > n) break;` as its inner loop termination instead of the correct trial-division condition `if (p * p > n) break;`. It also lacked the fallback `lambda[n] = Math.log(n)` for when no prime factor ≤ √n is found (meaning n is prime). Since getPrimes(100) only returns primes up to 541, any prime n > 541 would have no factor found in the list, the loop would exhaust all primes, and lambda[n] would remain 0 instead of log(n). This caused the Von Mangoldt Spectrum tab in FourierDomainViz to miss spectral contributions from all primes between 541 and maxN (slider goes up to 800), weakening the spectral peaks at zeta zero frequencies. Fixed by changing the break condition to p*p > n and adding the prime fallback after the loop." },
  { id: 105, timestamp: "2026-03-03T21:00:00Z", category: "accuracy", summary: "Fix Frequency Response explainer wrongly claiming resonances are sharpest at σ=0.5", files: ["FourierDomainViz.jsx"], detail: "The Frequency Response tab explainer stated 'At σ = 0.5, the peaks are sharpest (Q = 1)' and 'Moving σ off the critical line shifts and broadens these resonance peaks.' Both claims are wrong: since Q = 1/(2σ), lower σ gives higher Q and sharper resonances (Q → ∞ as σ → 0), while higher σ damps them. At σ = 0.5 the Q is merely 1 — moderate damping. The critical line is special because it balances the direct and dual ladders, not because resonances are sharpest there. Fixed the explainer to correctly describe the Q–σ relationship and clarify the role of σ = 0.5." },
  { id: 106, timestamp: "2026-03-03T12:00:00Z", category: "visual", summary: "Add category color legend to ExplorationGraphViz force-directed graph", files: ["ExplorationGraphViz.jsx"], detail: "The ExplorationGraphViz used 7 distinct category colors for node borders/fills (foundation, oscillator-model, duality, hamiltonian, control-theory, signal-processing, statistical) but had no legend explaining what the colors mean. Users could only discover a node's category by clicking it. Added a compact color legend in the top-right corner of the SVG showing all 7 categories with matching circle swatches, using the same fill+stroke style as the graph nodes." },
  { id: 107, timestamp: "2026-03-03T12:15:00Z", category: "performance", summary: "Memoize zetaMagnitudeScan in ExtendedLandscapeTab to avoid 300 zeta evaluations on resize", files: ["SupercriticalViz.jsx"], detail: "The ExtendedLandscapeTab called zetaMagnitudeScan(tValue, [sigmaMin, sigmaMax], 300) inside the draw callback, which fires on every window resize event. Each call performs 300 Borwein-accelerated zeta evaluations — expensive work that only needs to recompute when slider values change. Moved the scan into a useMemo hook with [tValue, sigmaMin, sigmaMax] dependencies, so window resize events now only repaint the canvas using cached data instead of recomputing all 300 zeta values." },
  { id: 108, timestamp: "2026-03-03T19:30:00Z", category: "content", summary: "Add zero-free regions as stability margins exploration entry connecting PNT error to Nyquist gain margin", files: ["explorations.js"], detail: "Added exploration exp-029 explaining how classical zero-free regions (de la Vallée-Poussin, Vinogradov-Korobov) translate to stability margins in the oscillator chain's Nyquist analysis. The entry shows that the PNT error term is directly controlled by the gain margin width, and that RH predicts a frequency-independent margin of 1/2. Connected to exp-007 (Nyquist stability) via nextSteps." },
  { id: 109, timestamp: "2026-03-03T12:30:00Z", category: "accuracy", summary: "Fix HamiltonianViz explainer wrongly claiming impedance mismatch vanishes at σ=0.5", files: ["HamiltonianViz.jsx"], detail: "The Hamiltonian explainer stated 'At σ = 0.5, mismatch vanishes (functional equation symmetry) ... leaving only the minimized kinetic term.' This is wrong: at σ = 0.5, the direct ladder at s = [½, t] and dual ladder at [½, −t] have impedances that are complex conjugates (Z_dir = [A, B], Z_dual = [A, −B]), so |Z_dir − Z_dual| = |[0, 2B]| ≠ 0. The impedances are conjugate-matched (equal real parts, opposite imaginary parts), which minimizes the mismatch but does not zero it. Fixed the text to correctly describe conjugate matching and the nonzero imaginary-part residual." },
  { id: 110, timestamp: "2026-03-03T13:00:00Z", category: "ux", summary: "Add nearest-zero proximity indicator to t slider in EulerProductViz", files: ["EulerProductViz.jsx"], detail: "The EulerProductViz t slider showed only the numeric value with no feedback about proximity to zeta zeros, despite every other component with a t slider having this indicator. Added the nearest-zero proximity display that turns green when t is within 0.3 of a zero and shows the subscript index and value (e.g. '≈ γ₁=14.1'), helping users quickly locate interesting zero-crossing behavior in the Euler product convergence." },
  { id: 111, timestamp: "2026-03-03T14:00:00Z", category: "visual", summary: "Add right-side y-axis for cumulative delay scale in Phase & Delay tab", files: ["WaveSimViz.jsx"], detail: "The PhaseDelayTab in WaveSimViz plotted cumulative delay dashed lines on a separate yCum scale from the per-prime delay bars, but had no right-side y-axis to indicate the cumulative scale. Users could not read cumulative delay values. Added a labeled right y-axis with ticks for the cumulative scale, widened the right margin to 60px, and expanded the legend to distinguish solid bars (per-prime delay) from dashed lines (cumulative delay) for both direct and dual ladders." },
  { id: 112, timestamp: "2026-03-03T18:30:00Z", category: "visual", summary: "Add missing axis labels to all three modes of LiCriterionViz", files: ["LiCriterionViz.jsx"], detail: "All three modes of LiCriterionViz (Li coefficients, Keiper-Li, de Bruijn-Newman) had no y-axis labels, making it unclear what quantity is plotted vertically. The Keiper-Li mode also lacked an x-axis label. Added rotated y-axis labels: 'λₙ' for the Li coefficients bar chart, 'λₙ/n' for the Keiper-Li scatter plot, and 'σ = Re(ρ)' for the de Bruijn-Newman zero drift plot. Also added the missing 'n' x-axis label to Keiper-Li mode." },
  { id: 113, timestamp: "2026-03-03T19:00:00Z", category: "bug", summary: "Fix DocsPage stale counts (13→15 pages, 16→17 viz) and add missing Waves and Improvements pages", files: ["DocsPage.jsx"], detail: "The DocsPage file structure section listed '13 route pages' and '16 visualization components' but the app actually has 15 routed pages and 17 visualization components. The page listing also omitted the Waves (/waves) and Improvements (/improvements) pages entirely, and the data directory description was missing improvements.js. Updated all counts and added the two missing page entries with descriptions." },
  { id: 114, timestamp: "2026-03-03T19:30:00Z", category: "accuracy", summary: "Fix bridge scattering matrix wrong sign: S₂₂ should be −Γ not +Γ for unitarity", files: ["OscillatorsPage.jsx"], detail: "The OscillatorsPage bridge scattering matrix formula showed S = ((Γ, τ), (τ, Γ)) with the same Γ in both diagonal entries. For a reciprocal lossless 2-port, S†S = I requires the (2,2) entry to be −Γ, not +Γ. With the old formula, the off-diagonal of S†S is 2Γτ ≠ 0, so the matrix is not unitary for Γ ≠ 0 (i.e. anywhere off the critical line). Fixed to S = ((Γ, τ), (τ, −Γ)) and clarified that unitarity holds everywhere (lossless by construction), with Γ = 0 specifically at σ = ½." },
  { id: 115, timestamp: "2026-03-03T20:00:00Z", category: "accuracy", summary: "Fix explainer calling ψ(x) 'the prime counting function' and giving wrong oscillation trig form", files: ["ExplicitFormulaViz.jsx"], detail: "The ExplicitFormulaViz explainer called ψ(x) 'the prime counting function,' but ψ(x) = Σ Λ(n) is the Chebyshev function (log-weighted prime-power count), not π(x). It also stated each zero contributes x^{1/2}cos(γ log x)/|ρ|, omitting the critical phase shift arg(ρ) ≈ π/2 that makes the dominant behavior sin(γ log x)/γ rather than cos. Fixed by correctly identifying ψ(x) as the Chebyshev function, distinguishing it from π(x), and giving the exact oscillation form -(2x^{1/2}/|ρ|)cos(γ log x - arg ρ) with the sin approximation." },
  { id: 116, timestamp: "2026-03-03T20:30:00Z", category: "ux", summary: "Show highest zero frequency (γ_max) next to Zeros Used slider in GUEStatisticsViz", files: ["GUEStatisticsViz.jsx"], detail: "The Zeros Used slider in GUEStatisticsViz showed only the count (e.g. '50') with no indication of what t-range those zeros span. Added a parenthetical γ_max display (e.g. '(γ_max ≈ 143.1)') next to the slider value, so users can see at a glance the height in the critical strip they are analyzing. This matches the same pattern already added to ExplicitFormulaViz in improvement #91." },
  { id: 117, timestamp: "2026-03-03T21:00:00Z", category: "visual", summary: "Add missing y-axis label to Gradient Descent bottom panel (σ vs Step)", files: ["TwinOscillatorSimViz.jsx"], detail: "The GradientDescentTab bottom panel showed σ convergence over gradient descent steps but had no y-axis label, while the top panel correctly labeled its y-axis 'H(σ)'. Without the label, the bottom chart's vertical axis was only identifiable from the two tick values (0.5 and the start σ). Added a rotated 'σ' label on the left edge, matching the style and positioning of the top panel's y-axis label." },
  { id: 118, timestamp: "2026-03-03T21:30:00Z", category: "visual", summary: "Add horizontal gridlines to all three modes of PrimeGapCouplingViz for easier value reading", files: ["PrimeGapCouplingViz.jsx"], detail: "All three modes of PrimeGapCouplingViz (coupling strength, prime gaps, oscillator frequencies) lacked horizontal gridlines, making it hard to read y-axis values precisely. Added dashed gridlines at the same tick positions as the y-axis labels, using the same subtle styling (#1e293b, dashed 4,4) already used in HamiltonianViz and ExplicitFormulaViz." },
  { id: 119, timestamp: "2026-03-03T22:00:00Z", category: "performance", summary: "Memoize ConvergenceTab curve data to avoid recomputing 378 Hamiltonian evaluations on resize", files: ["TwinOscillatorSimViz.jsx"], detail: "The ConvergenceTab computed allCurves (6 hamiltonianSigmaScan calls of 60 steps each, plus 18 systemHamiltonian calls for gradient/curvature) inside the draw callback, which fires on every window resize. Each systemHamiltonian internally runs 5 full ladder evaluations (direct, dual, bridge, plus 2 for gradient finite differences), totalling ~1890 ladder computations. Moved the heavy allCurves computation into useMemo with [tValue] dependency so resize events only redraw the SVG using cached data." },
  { id: 120, timestamp: "2026-03-03T22:30:00Z", category: "content", summary: "Add primon gas exploration entry connecting zeta partition function to oscillator chain thermodynamics", files: ["explorations.js"], detail: "Added exploration exp-030 explaining how the Riemann zeta function is literally the partition function of the primon gas — a free boson gas with one particle per prime at energy log(p). The entry derives thermodynamic quantities (free energy, internal energy, entropy), explains the Bost-Connes phase transition at σ=1, and connects the primon gas to the oscillator chain model. Linked from exp-029 via nextSteps and references julia-1990, bost-connes-1995, and knauf-1999." },
  { id: 121, timestamp: "2026-03-03T23:00:00Z", category: "content", summary: "Add Montgomery pair correlation exploration entry on level repulsion and GUE universality in the oscillator chain", files: ["explorations.js"], detail: "Added exploration exp-031 explaining Montgomery's 1973 pair correlation conjecture — the discovery that zeta zeros exhibit GUE level repulsion R₂(r) = 1 − (sin πr/πr)². The entry covers the historical Dyson tea-time connection, translates pair correlation into oscillator chain language (normal-mode repulsion from strong coupling), explains the Poisson-to-GUE transition, and notes Odlyzko's numerical verification at γ ≈ 10²⁰. Linked from exp-010 (GUE from coupled oscillators) and exp-030 (primon gas) via nextSteps." },
  { id: 122, timestamp: "2026-03-03T23:30:00Z", category: "bug", summary: "Fix spectralEnergyDensity dual ladder using conjugate s* instead of reflected (1−σ,ω)", files: ["supercritical.js"], detail: "The spectralEnergyDensity function computed the dual ladder at (1−σ, −ω) — the complex conjugate of 1−s — instead of (1−σ, +ω) as described in the Spectral Energy tab explainer. While energies |H|² are unaffected by conjugation (|H(s)| = |H(s̄)|), the impedance mismatch |Z_dir − Z_dual| was comparing Z(σ,ω) with Z̄(1−σ,ω) instead of Z(1−σ,ω). This caused the red mismatch curve to show 2|Im(Z)| at σ=0.5 instead of correctly vanishing to zero." },
  { id: 123, timestamp: "2026-03-03T23:45:00Z", category: "ux", summary: "Show largest prime (p_max) next to Primes slider count in AnimatedModesViz", files: ["AnimatedModesViz.jsx"], detail: "The Primes slider in AnimatedModesViz displayed only the count (e.g. '12') with no indication of which primes are included or how high the range extends. Added a parenthetical showing the largest prime in the set (e.g. '12 (up to p=37)'), so users can immediately see the oscillator frequency range without mentally mapping count to prime values." },
  { id: 124, timestamp: "2026-03-03T12:00:00Z", category: "accuracy", summary: "Fix AnimatedModesViz amplitude ignoring zero frequency γₙ (was 1/√p, now Re(p^{-1/2-iγₙ}))", files: ["AnimatedModesViz.jsx"], detail: "The AnimatedModesViz computed each prime oscillator's amplitude as 1/√p, which is independent of which zeta zero γₙ is selected. The explainer correctly states the amplitude should be ∝ Re(p^{-1/2-iγₙ}) = p^{-1/2}·cos(γₙ log p), which depends on the zero frequency. The old formula meant switching zeros changed only the spatial frequency of the waveform, but all primes always had positive, γ-independent amplitudes. The fix adds the cos(γₙ log p) factor, so different zeros now produce visibly different excitation patterns across the prime chain — some primes get phase-flipped (negative amplitude), and the interference pattern in the superposition row changes dramatically with zero selection." },
  { id: 125, timestamp: "2026-03-03T12:30:00Z", category: "visual", summary: "Add horizontal gridlines to all four ThermodynamicsTab charts in SupercriticalViz", files: ["SupercriticalViz.jsx"], detail: "The ThermodynamicsTab showed four stacked charts (Free Energy, Entropy, Pressure, Specific Heat) with y-axis tick marks but no horizontal gridlines extending across the chart width. Users could see tick values on the left edge but couldn't trace them across the plot to read values from the curves. Added dashed horizontal gridlines at each y-axis tick position using D3's tickSize(-w) pattern, styled in subtle #1e293b with dash pattern 4,4 to match the gridline style already used in HamiltonianViz and ExplicitFormulaViz." },
  { id: 126, timestamp: "2026-03-03T13:00:00Z", category: "performance", summary: "Hoist constant reference curves to module level in GUEStatisticsViz to avoid recomputing on every draw", files: ["GUEStatisticsViz.jsx"], detail: "GUEStatisticsViz recomputed five mathematical reference curves (GUE Wigner surmise, Poisson, GOE, pair correlation R₂, number variance GUE prediction) from scratch inside the draw callback on every render and window resize. These are pure mathematical constants — ~750 combined Math.exp/sin/log evaluations — that never depend on slider values. Hoisted all five curves to module-level constants computed once at import time, eliminating redundant transcendental function evaluations on every draw call." },
  { id: 127, timestamp: "2026-03-03T13:30:00Z", category: "performance", summary: "Memoize Nyquist and Bode loop-gain data to avoid recomputing 1104 zeta evaluations on resize", files: ["NyquistBodeViz.jsx"], detail: "Both drawNyquist (301 steps) and drawBode (251 steps) computed their loop-gain data inside the draw callback, which fires on every window resize event. Each step calls computeLoopGain requiring 2 zetaCriticalStrip evaluations plus a losslessBridge call, totalling ~1104 Borwein-accelerated zeta evaluations per resize. Extracted both data computations into useMemo hooks with [sigma, tRange] dependencies, so resize events now only repaint the SVG using cached data." },
  { id: 128, timestamp: "2026-03-03T14:00:00Z", category: "content", summary: "Add navigation guide card to ExplorationsPage explaining categories and depth scale", files: ["ExplorationsPage.jsx"], detail: "The ExplorationsPage listed 31 explorations with category tags and depth badges but provided no explanation of what the 7 categories represent or what the depth 1–6 scale means. Added a two-column guide card between the filter bar and the exploration entries. The left column explains each category with color-matched labels (foundation, oscillator-model, duality, hamiltonian, control-theory, signal-processing, statistical). The right column explains the depth scale (1–2 setup, 3–4 core theory, 5–6 advanced) and how to use the 'Leads to' links to trace the reasoning chain." },
  { id: 129, timestamp: "2026-03-03T14:30:00Z", category: "bug", summary: "Fix phase response chart using curveBasis interpolation across ±π atan2 wrap discontinuities", files: ["FourierDomainViz.jsx"], detail: "The FrequencyResponseTab phase chart used d3.curveBasis to draw the phase curve. Since Math.atan2 returns values in (−π, π], the phase wraps abruptly from +π to −π as the cumulative Euler product phase crosses ±π boundaries. The curveBasis spline smoothly interpolated across these discontinuities, drawing fake arcs that pass through 0 instead of showing the actual phase wrap. This made the phase chart visually misleading — it appeared to show the phase crossing zero when in reality it jumped. Changed to d3.curveLinear, which correctly renders the wraps as near-vertical jumps." },
  { id: 130, timestamp: "2026-03-03T15:00:00Z", category: "accuracy", summary: "Fix inverted de Bruijn-Newman heat flow direction: τ>0 preserves real zeros, τ<0 scatters them", files: ["supercritical.js", "SupercriticalViz.jsx"], detail: "The heatFlowZeros function displaced zeros off the critical line σ=1/2 for τ>0 (forward heat flow) and kept them fixed for τ<0. This is backwards: de Bruijn proved H_τ has only real zeros for τ≥Λ, and Rodgers-Tao showed Λ≥0, so forward heat flow (τ>0) preserves real zeros while backward flow (τ<0, inverse diffusion) can scatter them off the line. Fixed the sigma displacement condition from τ>0 to τ<0, corrected the explainer text, and swapped the color coding/labels so τ<0 (scatter) is orange and τ>0 (smooth) is blue." },
  { id: 131, timestamp: "2026-03-03T15:30:00Z", category: "bug", summary: "Fix inverted heat flow direction in LiCriterionViz de Bruijn-Newman scatter plot", files: ["LiCriterionViz.jsx"], detail: "The de Bruijn-Newman scatter plot in LiCriterionViz had the same inverted heat flow bug that was fixed in SupercriticalViz (#130). Zero perturbations were applied for τ>0 (forward heat) and suppressed for τ≤0, but de Bruijn proved H_τ has only real zeros for τ≥Λ≥0, so forward heat preserves zeros on the line while backward flow (τ<0) scatters them. Fixed the perturbation condition from τ>0 to τ<0 and corrected the explainer text to say τ>0 preserves real zeros rather than pushing them off." },
  { id: 132, timestamp: "2026-03-03T16:00:00Z", category: "bug", summary: "Fix BridgeTab annotation using ASCII 'chi' instead of Unicode 'χ' for bridge magnitude label", files: ["TwinOscillatorSimViz.jsx"], detail: "The BridgeTab's |χ(s)| vs σ chart annotated the σ=0.5 critical-line dot with the label '|chi| = ...' using ASCII text, while the chart title directly below used the correct Unicode Greek letter '|χ(s)| vs σ'. This display inconsistency made the annotation look like a code artifact rather than a proper mathematical label. Changed '|chi|' to '|χ|' to match the chart title and all other Unicode Greek usage throughout the visualization." },
  { id: 133, timestamp: "2026-03-03T16:30:00Z", category: "accuracy", summary: "Fix de Bruijn-Newman 'Look for' text contradicting corrected heat flow direction", files: ["LiCriterionViz.jsx"], detail: "The de Bruijn-Newman tab explainer's 'Look for' directive told users to watch for 'zeros migrating off the real axis as τ increases from 0', contradicting the corrected physics: forward heat (τ>0) preserves real zeros, while backward heat (τ<0) scatters them. This text was a leftover from the inverted heat flow bug fixed in #131 — the code perturbation condition was corrected but the 'Look for' line was not updated. Changed to correctly say zeros stay on σ=½ for τ≥0 and scatter off for τ<0." },
  { id: 134, timestamp: "2026-03-03T17:00:00Z", category: "ux", summary: "Show largest prime (p_max) next to Primes slider count in HamiltonianViz", files: ["HamiltonianViz.jsx"], detail: "The Primes slider in HamiltonianViz displayed only the count (e.g. '10') with no indication of which primes are included or how high the range extends. Added a parenthetical showing the largest prime in the set (e.g. '10 (up to p=29)'), matching the pattern already used in AnimatedModesViz (#123). This lets users immediately see the oscillator frequency range without mentally mapping prime counts to prime values." },
  { id: 135, timestamp: "2026-03-03T18:00:00Z", category: "visual", summary: "Add horizontal gridlines to MultiZeroTab scatter plot for easier σ_min reading", files: ["TwinOscillatorSimViz.jsx"], detail: "The Multi-Zero Test scatter plot showed σ_min dots against y-axis ticks at 0.30–0.70, but had no horizontal gridlines — users couldn't trace tick marks across the plot to read exact σ_min values from the dots. Added dashed gridlines at each y-axis tick using D3's tick values, styled in subtle #1e293b to match the dark theme and other gridline improvements (#40, #63, #118). This makes it easier to verify whether dots cluster precisely at σ=0.5 or deviate slightly." },
  { id: 136, timestamp: "2026-03-03T18:30:00Z", category: "performance", summary: "Memoize 10,000-cell heatmap grid in ZetaLandscapeViz to avoid recomputing zeta on resize", files: ["ZetaLandscapeViz.jsx"], detail: "The drawHeatmap callback computed 100×100 = 10,000 zetaCriticalStrip evaluations (each using Borwein acceleration with N=50 terms) inside the useCallback, which re-fires on every window resize event. The grid data only depends on tRange and sigmaRange, not canvas dimensions. Extracted the grid computation into a useMemo hook with [tRange, sigmaRange] dependencies and stored normalized magnitudes in a Float64Array. Now resize events only repaint the cached grid to the canvas, eliminating 10,000 redundant zeta evaluations per resize." },
  { id: 137, timestamp: "2026-03-03T19:00:00Z", category: "content", summary: "Add observation guide card to OscillatorsPage explaining what to look for in chain and Euler product", files: ["OscillatorsPage.jsx"], detail: "The OscillatorsPage is the core page introducing the ZPO model but had no 'What to Observe' guide card to help users explore the two interactive visualizations. Added a green-bordered guide card with three bullet points: (1) how to inspect oscillator nodes and observe critical coupling Q=1 at σ=0.5 vs lossy bridge off-line, (2) how to read the Euler product bar chart and watch convergence collapse near zeta zeros, (3) how to see direct/dual ladder symmetry break as σ leaves the critical line." },
  { id: 138, timestamp: "2026-03-03T19:30:00Z", category: "content", summary: "Add Keating-Snaith moment conjecture exploration entry on power statistics of the oscillator chain output", files: ["explorations.js"], detail: "Added exploration exp-032 on the Keating-Snaith moment conjecture — the prediction that E[|ζ(1/2+it)|^{2k}] grows as (log T)^{k²}. The entry derives the k² exponent from CUE random matrix theory, explains the arithmetic/universal factorization C_k = a_k · g_k, interprets moments as power statistics of the oscillator chain output signal, and connects the Euler product cascade to log-normal amplitude statistics via Selberg's CLT. Linked from exp-010 (GUE) and exp-031 (pair correlation) via nextSteps." },
  { id: 139, timestamp: "2026-03-03T20:00:00Z", category: "bug", summary: "Fix phase mode using curveBasis interpolation across ±π atan2 wrap discontinuities in ScatteringMatrixViz", files: ["ScatteringMatrixViz.jsx"], detail: "The ScatteringMatrixViz phase mode used d3.curveBasis to draw the arg(χ) curve. Since Math.atan2 returns values in (−π, π], the phase wraps abruptly from +π to −π as the cumulative bridge phase crosses ±π boundaries. The curveBasis B-spline smoothly interpolated across these discontinuities, drawing fake arcs that pass through 0° instead of showing the actual phase wrap. This is the same bug that was fixed in FourierDomainViz (improvement #129). Changed to d3.curveLinear, which correctly renders the wraps as near-vertical jumps." },
  { id: 140, timestamp: "2026-03-03T20:30:00Z", category: "accuracy", summary: "Fix EnergyLandscapeViz explainer claiming mismatch shows |Z|² and is zero on critical line", files: ["EnergyLandscapeViz.jsx"], detail: "The EnergyLandscapeViz explainer stated the Impedance Mismatch metric shows |Z_dir − Z_dual|² and is 'zero on the critical line.' Both claims are wrong. The code computes cAbs(cSub(Z_dir, Z_dual)) which is the unsquared norm |Z_dir − Z_dual|, not the square. And at σ=0.5, the direct and dual impedances are complex conjugates (Z_dual = Z̄_dir), so their difference is 2i·Im(Z) ≠ 0 — the mismatch is minimized but not zero. This is the same conjugate-matching issue fixed in HamiltonianViz (#109). Corrected the LaTeX to show the unsquared norm and changed 'zero' to 'minimized (not zero)' with a note about conjugate matching." },
  { id: 141, timestamp: "2026-03-03T21:00:00Z", category: "ux", summary: "Show largest prime (p_max) next to Max Primes slider count in EulerProductViz", files: ["EulerProductViz.jsx"], detail: "The Max Primes slider in EulerProductViz displayed only the count (e.g. '30') with no indication of which primes are included or how high the range extends. Added a parenthetical showing the largest prime in the set (e.g. '30 (up to p=127)'), matching the pattern already used in HamiltonianViz (#134) and AnimatedModesViz (#123). This lets users immediately see the oscillator frequency range without mentally mapping prime counts to prime values." },
  { id: 142, timestamp: "2026-03-03T21:30:00Z", category: "visual", summary: "Scale horizontal connector opacity and width by per-stage magnitude in OscillatorChainViz", files: ["OscillatorChainViz.jsx"], detail: "The horizontal dashed connectors between the direct/dual oscillator nodes and the central bridge column were all drawn with identical styling (opacity 0.25, stroke-width 0.8) regardless of the signal strength at each stage. This made every coupling link look the same, hiding which prime stages carry the most signal. Changed connector opacity to scale from 0.12 to 0.50 and width from 0.6 to 2.0, proportional to each stage's transfer function magnitude normalized by the peak magnitude across both ladders. Users can now visually identify the strongest-coupled prime stages at a glance." },
  { id: 143, timestamp: "2026-03-03T22:00:00Z", category: "performance", summary: "Memoize primeHarmonicDecomposition to eliminate duplicate computation in PrimeHarmonicsTab", files: ["FourierDomainViz.jsx"], detail: "The PrimeHarmonicsTab called primeHarmonicDecomposition(sigma, numPrimes) twice per render: once inside the draw useCallback (for the SVG bar chart) and again in the component render body (for the stat grid). Each call computes harmonic magnitudes for up to 50 primes with multiple overtones. Extracted the computation into a single useMemo hook with [sigma, numPrimes] dependencies, eliminating the duplicate call and also preventing recomputation on window resize events, which only need to repaint the SVG using cached data." },
  { id: 144, timestamp: "2026-03-03T22:30:00Z", category: "content", summary: "Add suggested learning path to HomePage guiding users through pages in logical progression", files: ["HomePage.jsx"], detail: "The HomePage had page navigation cards and a mathematical correspondences table but no guidance on reading order. For an app with 15 pages covering advanced topics from LC resonators to GUE statistics, first-time visitors had no way to know where to start or how concepts build on each other. Added a numbered 10-step learning path between the Core Idea cards and the correspondences table, progressing from Oscillators (the foundational model) through Hamiltonian, Zeta, Fourier, Control Theory, Statistics, Simulator, Modes, Supercritical, and Waves — each step with a brief description of what the user will learn and why it follows from the previous page." },
  { id: 145, timestamp: "2026-03-03T23:00:00Z", category: "content", summary: "Add visualization-by-visualization exploration guide card to ModesPage", files: ["ModesPage.jsx"], detail: "The ModesPage had four visualizations (Animated Modes, Prime Gap Coupling, Energy Landscape, Exploration Graph) but no guide card explaining what to look for in each one. Other pages like FourierPage, StatisticsPage, and SupercriticalPage all have 'What to Explore in Each Tab' guide cards. Added a green-bordered guide card between the mode anatomy cards and the first visualization, with color-coded descriptions for each viz: Animated Modes (phase-flip patterns across primes for different zeros), Prime Gap Coupling (twin prime spikes and logarithmic dispersion), Energy Landscape (critical-line valley and hover inspection), and Exploration Graph (node dragging and reasoning chain tracing)." },
  { id: 146, timestamp: "2026-03-03T23:30:00Z", category: "bug", summary: "Fix Bode phase plot using curveBasis interpolation across ±180° atan2 wrap discontinuities", files: ["NyquistBodeViz.jsx"], detail: "The Bode diagram phase plot in NyquistBodeViz used d3.curveBasis to draw the phase curve. Since Math.atan2 returns values in (−π, π] (converted to ±180°), the phase wraps abruptly at ±180° boundaries. The curveBasis B-spline smoothly interpolated across these discontinuities, drawing fake arcs through 0° instead of showing the actual phase wraps. This is the same bug that was fixed in FourierDomainViz (#129) and ScatteringMatrixViz (#139). Changed to d3.curveLinear, which correctly renders the wraps as near-vertical jumps." },
  { id: 147, timestamp: "2026-03-04T00:00:00Z", category: "ux", summary: "Add hover tooltips to all data bars and dots in PrimeGapCouplingViz showing prime pair, gap, and coupling info", files: ["PrimeGapCouplingViz.jsx"], detail: "The PrimeGapCouplingViz had three interactive modes (coupling strength, prime gaps, natural frequencies) but none of the data elements showed any information on hover — users had to visually estimate bar heights and dot positions from the axes. Added SVG title-element tooltips to all data shapes across all three modes: coupling bars show the prime pair (p₁→p₂), gap size, twin prime status, and coupling value Y; gap bars show the prime pair and gap size with twin annotation; frequency dots show the prime p and its natural frequency ω=log(p). Also set cursor to crosshair on all interactive elements." },
  { id: 148, timestamp: "2026-03-03T23:45:00Z", category: "bug", summary: "Fix EulerPhaseTab average factor magnitude line drawn as static orange instead of green/red convergence coloring", files: ["SupercriticalViz.jsx"], detail: "The EulerPhaseTab bottom chart ('Average Euler factor magnitude') had a comment saying 'Color the line by convergence' but drew the entire curve in static orange (#f59e0b). The explainer text told users to 'Look for: the sharp transition from convergent (green) to divergent (red) at σ=1', but no such color transition existed. Split the line into two segments: red (#ef4444) for σ≤1 (divergent region where the Euler product fails to converge) and green (#10b981) for σ≥1 (convergent region), making the Bost-Connes phase transition boundary visually obvious." },
  { id: 149, timestamp: "2026-03-03T12:00:00Z", category: "visual", summary: "Add y-axis tick marks and amplitude gridlines to critical-line Z(t) chart in ZetaLandscapeViz", files: ["ZetaLandscapeViz.jsx"], detail: "The critical-line Z(t) chart had x-axis grid labels (t=5, t=10, etc.) but no y-axis tick marks or amplitude labels — users could see the Z(t) waveform but had no way to read its actual amplitude values. Added dashed horizontal gridlines at nicely-spaced intervals (auto-scaled based on the maximum amplitude) with numeric labels on the left edge, matching the gridline style used elsewhere (e.g. HamiltonianViz, ExplicitFormulaViz). The zero line is skipped since it is already drawn separately." },
  { id: 150, timestamp: "2026-03-03T12:30:00Z", category: "accuracy", summary: "Fix stale docstring comments claiming τ>0 scatters zeros (actually τ<0 does) in supercritical.js", files: ["supercritical.js"], detail: "The heatFlowZeros docstring (lines 179-180) still claimed 'For τ>0, zeros move off the real line' and 'For τ<0, zeros are pushed onto the real line' — both statements are backwards. Improvement #130 fixed the code behavior but missed these comments. De Bruijn proved H_τ has only real zeros for τ ≥ Λ, and Rodgers-Tao showed Λ ≥ 0, so τ>0 (forward heat) preserves real zeros while τ<0 (backward heat) scatters them. Also fixed a related comment in heatEvolvedXi that incorrectly cited Rodgers-Tao as proving zeros stay real for τ ≤ 0 instead of τ ≥ 0." },
  { id: 151, timestamp: "2026-03-03T21:00:00Z", category: "accuracy", summary: "Fix number variance explainer showing leading-order asymptotic instead of the full GUE formula actually plotted", files: ["GUEStatisticsViz.jsx"], detail: "The number variance explainer text displayed the leading-order asymptotic Σ²(L) ~ (2/π²) log L, but the red GUE reference curve actually plots the full formula (2/π²)(log(2πL) + 1 + γ_E − π²/8) which includes the sub-leading constants. The formulas differ by a constant offset of ~0.44, so users trying to verify the curve against the stated formula would find a systematic discrepancy. Updated the LaTeX to show the complete formula matching the plotted reference curve." },
  { id: 152, timestamp: "2026-03-03T23:00:00Z", category: "ux", summary: "Add nearest-zero proximity indicator to t slider in EulerPhaseTab", files: ["SupercriticalViz.jsx"], detail: "The Euler Product Phase tab's t slider displayed only the numeric value (e.g. '14.1') with no indication of which zeta zero the user is near. Since the Euler product phase behavior is strongly influenced by nearby zeros, this context is essential for interpreting the charts. Added a nearest-zero proximity indicator matching the pattern used in the ThermodynamicsTab (#55): when within distance 1 of a zero, shows '≈ γₙ=14.1' in subscript notation, turning green when within 0.3 of the zero." },
  { id: 153, timestamp: "2026-03-03T23:30:00Z", category: "visual", summary: "Add horizontal gridlines to both Bode magnitude and phase panels in NyquistBodeViz", files: ["NyquistBodeViz.jsx"], detail: "The Bode diagram had axis ticks but no horizontal gridlines in either the magnitude (dB) or phase (degrees) panel, making it difficult to read values away from the axis. Added dashed horizontal gridlines to both panels matching the style used throughout the app (e.g. HamiltonianViz, ExplicitFormulaViz, SupercriticalViz): subtle #1e293b dashed lines at each tick mark. The 0 dB and -180° reference lines remain separately styled in red for emphasis." },
  { id: 154, timestamp: "2026-03-03T23:50:00Z", category: "performance", summary: "Memoize Li coefficient and de Bruijn-Newman scatter data to avoid recomputing on resize", files: ["LiCriterionViz.jsx"], detail: "All three modes of LiCriterionViz (Li coefficients, Keiper-Li, de Bruijn-Newman) computed their data arrays inside the draw() callback, which runs on every window resize. The Li and Keiper-Li modes compute O(numZeros × maxN) polar-form powers (up to 200 × 40 = 8,000 Math.pow + trig calls), and the de Bruijn-Newman mode computes 8 × numZeros scatter positions. Extracted all data computation into a useMemo with [numZeros, maxN, mode] dependencies, so resize events only re-render the cached D3 elements without recomputing any math." },
  { id: 155, timestamp: "2026-03-03T19:00:00Z", category: "content", summary: "Add Voronin universality exploration entry connecting oscillator chain ergodicity to universal approximation", files: ["explorations.js"], detail: "Added exploration exp-033 on Voronin's universality theorem — the result that ζ(s+iτ) can approximate any non-vanishing holomorphic function as τ varies. The entry explains how universality arises from the Q-linear independence of {log p} making prime oscillator phases jointly ergodic on the infinite torus, why the non-vanishing condition reflects the cascade's inability to produce zero output, and Bagchi's result that RH is equivalent to ζ being self-approximating. Linked from exp-032 (Keating-Snaith moments) via nextSteps." },
  { id: 156, timestamp: "2026-03-03T12:45:00Z", category: "bug", summary: "Fix EulerProductViz phase curve using curveMonotoneX across ±π atan2 wrap discontinuities", files: ["EulerProductViz.jsx"], detail: "The EulerProductViz phase curve (arg(ζ) plotted against prime index) used d3.curveMonotoneX interpolation. Since Math.atan2 returns values in (−π, π], the phase wraps abruptly at ±π boundaries. The monotone cubic interpolated smoothly across these discontinuities, drawing fake arcs through 0 instead of showing the actual phase wraps. This is the same class of bug fixed in FourierDomainViz (#129), ScatteringMatrixViz (#139), and NyquistBodeViz (#146). Changed to d3.curveLinear to correctly render wraps as near-vertical jumps." },
  { id: 157, timestamp: "2026-03-03T20:30:00Z", category: "bug", summary: "Fix D3 force simulation not stopped on unmount in ExplorationGraphViz causing CPU leak", files: ["ExplorationGraphViz.jsx"], detail: "The ExplorationGraphViz created a D3 force simulation in its draw callback but never stopped it on component unmount. When the user navigated away from the Modes page, the simulation continued running via d3.timer in the background — computing forces and attempting to update detached SVG elements — until it naturally cooled down (several seconds of wasted CPU). Added a simRef to store the simulation instance and a cleanup function in the useEffect that calls simulation.stop() on unmount, immediately halting the timer." },
  { id: 158, timestamp: "2026-03-03T13:15:00Z", category: "accuracy", summary: "Fix Wave Interference explainer using wrong term 'constructive interference' for amplitude matching", files: ["WaveSimViz.jsx"], detail: "The Wave Interference tab explainer described the near-zero difference between direct and dual ladder waves at σ=0.5 as 'constructive interference / perfect match.' This is wrong: constructive interference means waves add to produce a larger amplitude. When the difference between two waves is near zero, it means the waves are identical — this is amplitude matching from direct/dual symmetry, not constructive interference. Changed to 'matched amplitudes from direct/dual symmetry' which correctly describes the phenomenon." },
  { id: 159, timestamp: "2026-03-03T13:30:00Z", category: "ux", summary: "Show largest prime (p_max) next to Primes slider count in SupercriticalViz ThermodynamicsTab and EulerPhaseTab", files: ["SupercriticalViz.jsx"], detail: "The Primes sliders in both the Thermodynamics and Euler Product Phase tabs of SupercriticalViz displayed only the count (e.g. '15') without indicating what the largest included prime is. This is inconsistent with the p_max companion display added to HamiltonianViz (#134), EulerProductViz (#141), and AnimatedModesViz (#123). Added '(up to p=N)' in subdued gray text next to both slider values, so users immediately know the range of primes included in the partition function and Euler product computations." },
  { id: 160, timestamp: "2026-03-03T14:00:00Z", category: "visual", summary: "Add horizontal gridlines to Von Mangoldt Spectrum tab for easier magnitude reading", files: ["FourierDomainViz.jsx"], detail: "The Von Mangoldt Spectrum tab in FourierDomainViz had axis ticks but no horizontal gridlines, making it difficult to read |F(ω)| magnitudes away from the y-axis. This was inconsistent with most other visualizations in the app (ExplicitFormulaViz, HamiltonianViz, PrimeGapCouplingViz, NyquistBodeViz, SupercriticalViz) which all have dashed gridlines. Added subtle #1e293b dashed gridlines at each y-tick mark, matching the existing app-wide style." },
  { id: 161, timestamp: "2026-03-03T14:30:00Z", category: "visual", summary: "Show dual ladder |ζ(1−s)| in OscillatorChainViz top-right summary alongside direct |ζ(s)|", files: ["OscillatorChainViz.jsx"], detail: "The OscillatorChainViz top-right summary showed s, |ζ(s)| (direct ladder), and bridge stats, but omitted |ζ(1−s)| (dual ladder). Since the visualization's entire purpose is showing the direct/dual symmetry of the oscillator chain, this asymmetry left users unable to compare the two ladder outputs at a glance. Added a gold-colored |ζ(1−s)| line between the blue |ζ(s)| and bridge stats, matching the dual ladder's existing gold color scheme and completing the symmetry of the summary display." },
  { id: 162, timestamp: "2026-03-03T15:00:00Z", category: "performance", summary: "Memoize Euler product and true zeta computations to avoid recomputing on resize", files: ["EulerProductViz.jsx"], detail: "The EulerProductViz draw callback computed partialEulerProduct (up to 100 prime stages with complex arithmetic per factor) and zetaCriticalStrip (Borwein-accelerated analytic continuation) on every call, including window resize events that only need to repaint the SVG. Extracted both computations into useMemo hooks — eulerData with [sigma, t, maxPrimes] deps and trueZetaMag with [sigma, t] deps — so resize events reuse cached results and only recompute when the actual parameters change." },
  { id: 163, timestamp: "2026-03-03T15:30:00Z", category: "content", summary: "Add Gram points exploration entry connecting theta function phase ticks to oscillator mode spacing", files: ["explorations.js"], detail: "Added exploration exp-034 on Gram points — the values g_n where the Riemann-Siegel theta function θ(g_n)=nπ. The entry explains how Gram points form a natural clock for the oscillator chain (each tick is one π of accumulated phase), how Gram's law predicts one zero per clock interval matching the Weyl-law mode spacing, and how Lehmer violations (mode bunching) connect to GUE level repulsion. Linked from exp-020 (Riemann-Siegel) and exp-033 (Voronin universality) via nextSteps." },
  { id: 164, timestamp: "2026-03-03T16:00:00Z", category: "content", summary: "Add per-visualization exploration guide card to HamiltonianPage for energy and explicit formula charts", files: ["HamiltonianPage.jsx"], detail: "The HamiltonianPage had two interactive visualizations (Hamiltonian Energy vs σ and Explicit Formula ψ(x)) but unlike FourierPage, ModesPage, StatisticsPage, SupercriticalPage, and WaveSimPage, had no 'What to Explore' guide card. Added a green-bordered guide card between the main formula and the first visualization, with two paragraphs: one for the energy chart (drag t to zeros, compare kinetic/mismatch/bridge components, increase primes to deepen the valley) and one for the explicit formula (add zeros to watch spectral convergence, observe shaded error area, look for log(p) jumps at prime powers)." },
  { id: 165, timestamp: "2026-03-03T16:30:00Z", category: "bug", summary: "Fix AnimatedModesViz pause resetting animation to t=0 instead of freezing in place", files: ["AnimatedModesViz.jsx"], detail: "When the user paused the AnimatedModesViz animation, the useEffect called draw(0) which snapped the visualization back to its initial state instead of freezing at the current frame. Added an elapsedRef to track the accumulated animation time. On pause, draw(elapsedRef.current) preserves the current frame. On resume, startTime is offset by the saved elapsed time so the animation continues smoothly from where it left off." },
  { id: 166, timestamp: "2026-03-03T17:00:00Z", category: "accuracy", summary: "Fix PerPrimeTab explainer wrongly attributing dual symmetry to the functional equation", files: ["TwinOscillatorSimViz.jsx"], detail: "The Per-Prime Energy tab explainer stated that |H_p(s)|² + |H_p(1−s)|² is symmetric about σ = ½ 'via the functional equation.' This is wrong: the functional equation ζ(s) = χ(s)ζ(1−s) relates the full zeta function, not individual Euler factors. The symmetry of f(σ) + f(1−σ) about σ = ½ is a trivial algebraic identity that holds for any function f — it's a property of the dual pairing construction, not the functional equation. Fixed the text to correctly attribute the symmetry to the s ↔ 1−s pairing." },
  { id: 167, timestamp: "2026-03-03T17:30:00Z", category: "accuracy", summary: "Fix explicit formula display omitting trivial zeros term ½log(1 − x⁻²)", files: ["ExplicitFormulaViz.jsx"], detail: "The ExplicitFormulaViz explainer displayed the explicit formula as ψ(x) = x − Σ_ρ x^ρ/ρ − log 2π, omitting the trivial zeros contribution −½log(1 − x⁻²). The code (primes.js) correctly includes this term in the computation, but the displayed formula was incomplete. While the term is small (it approaches 0 as x grows), it is mathematically significant — it accounts for the contribution of the trivial zeros at s = −2, −4, −6, ... and is necessary for the formula to be exact. Added the missing term to the KaTeX display." },
  { id: 168, timestamp: "2026-03-03T18:00:00Z", category: "ux", summary: "Show largest prime (p_max) next to Primes slider count in WaveSimViz", files: ["WaveSimViz.jsx"], detail: "The Primes slider in WaveSimViz displayed only the count (e.g. '8') with no indication of which primes are included or how high the range extends. Added a parenthetical showing the largest prime in the set (e.g. '8 (up to p=19)'), matching the pattern already used in HamiltonianViz (#134), AnimatedModesViz (#123), EulerProductViz (#141), and SupercriticalViz (#159). This lets users immediately see the oscillator frequency range without mentally mapping prime counts to prime values." },
  { id: 169, timestamp: "2026-03-03T18:30:00Z", category: "bug", summary: "Fix Riemann-Siegel C₀ correction producing NaN at removable singularities p=1/4 and p=3/4", files: ["zeta.js"], detail: "The Riemann-Siegel C₀ correction term cos(2π(p²−p−1/16))/cos(2πp) has removable singularities at p=1/4 and p=3/4 where both numerator and denominator are zero. Without a guard, specific t values (≈9.82, 19.24, 31.81, 47.52, ...) caused division by zero producing NaN/Infinity that propagated into all visualizations using riemannSiegelZ. By Taylor expansion, both singularities have a well-defined limit of 1/2. Added a denominator check with fallback to the analytically correct limit value." },
  { id: 170, timestamp: "2026-03-03T19:00:00Z", category: "visual", summary: "Add horizontal gridlines to PerPrimeTab and BridgeTab charts in TwinOscillatorSimViz", files: ["TwinOscillatorSimViz.jsx"], detail: "The Per-Prime Energy tab and both Bridge Unitarity side-by-side charts (|χ(s)| vs σ and Reflection Coefficient vs σ) had axis ticks but no horizontal gridlines, making it difficult to compare energy values across primes and read exact bridge/reflection values away from the y-axis. Added subtle #1e293b dashed gridlines at each y-tick mark to all three charts, matching the existing app-wide gridline style." },
  { id: 171, timestamp: "2026-03-03T19:30:00Z", category: "performance", summary: "Memoize explicit formula data arrays to avoid recomputing psiTable and zero sums on resize", files: ["ExplicitFormulaViz.jsx"], detail: "The ExplicitFormulaViz draw callback computed all data arrays (actualData, approxData, errorData) including the O(maxX) psiTable construction and O(steps × numZeros) explicitFormulaTerms calls on every invocation — including window resize events that only need to repaint the SVG. With maxX=500 and numZeros=200, this meant ~40,000 complex arithmetic operations wasted on each resize. Extracted all data computation into a useMemo with [maxX, numZeros] dependencies so resize events reuse cached arrays." },
  { id: 172, timestamp: "2026-03-03T20:00:00Z", category: "content", summary: "Add Dirichlet L-functions exploration entry on character-twisted oscillator chains and GRH", files: ["explorations.js"], detail: "Added exploration exp-035 on Dirichlet L-functions and the Generalized Riemann Hypothesis. The entry explains how each Dirichlet character χ twists the Euler product by inserting phase shifters χ(p) into every oscillator stage, how the functional equation still yields a lossless bridge on σ=1/2, why GRH (not just RH) is what most applications need, and how Katz-Sarnak symmetry types (unitary, symplectic, orthogonal) arise from different character twists. Linked from exp-001 (Euler product) and exp-017 (Beurling primes) via nextSteps." },
  { id: 173, timestamp: "2026-03-03T20:30:00Z", category: "content", summary: "Add Riemann-Siegel formula computation explainer card to ZetaPage", files: ["ZetaPage.jsx"], detail: "The ZetaPage showed the Z(t) definition but never explained how it is computed. Added a card breaking down the Riemann-Siegel formula into its main sum (cosine oscillations at frequencies log n, connecting to oscillator modes), correction term C₀(p) (truncation compensation improving accuracy from O(t^{-1/4}) to O(t^{-3/4})), and theta function (phase accumulator whose derivative gives zero density via the Weyl law). This fills the explanatory gap on the app's primary zeta function page." },
  { id: 174, timestamp: "2026-03-03T21:00:00Z", category: "bug", summary: "Fix DocsPage stale counts (15→16 pages, 17→18 viz) and add missing Rigor page, WaveSimViz, RHRigorViz entries", files: ["DocsPage.jsx"], detail: "The DocsPage file structure comment said '17 visualization components' and '15 route pages' but the actual app has 18 viz components and 16 pages after the Rigor page and RHRigorViz were added. The Pages section omitted /rigor, the Visualizations table omitted WaveSimViz and RHRigorViz (16 entries instead of 18), the intro text said '16 interactive visualization components', and the data/ listing omitted criticisms.js. Updated all counts and added the missing entries to match the actual codebase." },
  { id: 175, timestamp: "2026-03-03T21:30:00Z", category: "bug", summary: "Fix spectralEnergyDensity dual ladder using wrong sign for imaginary part (ω instead of −ω)", files: ["supercritical.js"], detail: "The spectralEnergyDensity function computed the dual ladder at [1−σ, ω] instead of the correct [1−σ, −ω]. The functional equation dual of s = σ+iω is 1−s = (1−σ)−iω, requiring the imaginary part to be negated. A previous fix (#122) changed from conjugate s* to reflected sigma but didn't negate omega. This made the dual identical to the direct ladder on σ=0.5 (since ω = −ω only when ω=0 or s is real), masking the impedance mismatch that should appear off the critical line. Replaced with dualLadder(s, numPrimes) which correctly applies the full 1−s transformation including omega negation." },
  { id: 176, timestamp: "2026-03-03T22:00:00Z", category: "bug", summary: "Fix EnergyLandscapeViz missing window resize handler causing blurry/distorted heatmap", files: ["EnergyLandscapeViz.jsx"], detail: "The EnergyLandscapeViz canvas-based heatmap had no window resize event listener, unlike every other visualization in the app (SVG-based ones like HamiltonianViz, GUEStatisticsViz, LiCriterionViz, etc. and canvas-based ones like ExtendedLandscapeTab and RHRigorViz). When the browser window was resized, the canvas CSS dimensions changed (width: 100%) but the pixel buffer remained at the old size, causing the heatmap to appear stretched and blurry. Added a resize useEffect matching the standard pattern used throughout the codebase: listen for 'resize', call draw(), clean up on unmount." },
  { id: 177, timestamp: "2026-03-03T22:30:00Z", category: "ux", summary: "Show largest prime (p_max) next to Primes slider count in RHRigorViz", files: ["RHRigorViz.jsx"], detail: "The Primes slider in RHRigorViz displayed only the count (e.g. '15') without indicating which primes are included. Since the rigor stress tests depend heavily on how many Euler factors are used — and the largest prime determines the oscillator frequency range — users need to know p_max at a glance. Added a parenthetical '(up to p=N)' in subdued gray text, matching the pattern already used in HamiltonianViz (#134), AnimatedModesViz (#123), EulerProductViz (#141), WaveSimViz (#168), and SupercriticalViz (#159)." },
  { id: 178, timestamp: "2026-03-03T23:00:00Z", category: "accuracy", summary: "Fix StatisticsPage de Bruijn-Newman description claiming positive τ scatters zeros (actually negative τ does)", files: ["StatisticsPage.jsx"], detail: "The StatisticsPage 'What to Explore' section described the de Bruijn-Newman tab as: 'positive τ pushes them apart into the complex plane.' This is backwards — improvements #130-133 corrected the heat flow direction in LiCriterionViz (τ>0 preserves real zeros, τ<0 scatters them), but the StatisticsPage description was missed. By de Bruijn's theorem, H_τ has only real zeros for τ ≥ Λ, and Rodgers-Tao proved Λ ≥ 0, so forward heat (τ>0) preserves real zeros while backward heat (τ<0) scatters them. Updated to correctly state that negative τ scatters zeros and positive τ preserves them." },
  { id: 179, timestamp: "2026-03-03T23:30:00Z", category: "visual", summary: "Add horizontal gridlines to all three modes of ScatteringMatrixViz", files: ["ScatteringMatrixViz.jsx"], detail: "The ScatteringMatrixViz had axis ticks but no horizontal gridlines in any of its three modes (magnitude, reflection, phase), making it difficult to read exact y-values away from the y-axis. Added subtle #1e293b dashed gridlines at each y-tick mark to all three chart modes, matching the existing app-wide gridline style used in HamiltonianViz, PrimeGapCouplingViz, FourierDomainViz, and TwinOscillatorSimViz." },
  { id: 180, timestamp: "2026-03-03T23:45:00Z", category: "visual", summary: "Add legends to both EulerPhaseTab charts showing convergence coloring and reference lines", files: ["SupercriticalViz.jsx"], detail: "The EulerPhaseTab in SupercriticalViz had two charts with important color-coded visual information but no legends. The top chart (Euler product log-magnitude) draws dashed vertical lines for the critical line (σ=½, red) and convergence boundary (σ=1, amber) with no indication of what they represent. The bottom chart (average factor magnitude) colors the curve red for σ<1 (divergent) and green for σ>1 (convergent), but this meaningful color transition had no legend. Added semi-transparent legend boxes to both charts with color-matched swatches and labels." },
  { id: 181, timestamp: "2026-03-03T23:55:00Z", category: "bug", summary: "Fix blurry canvas rendering on retina displays in WaveSimViz SignalFlowTab and WaveInterferenceTab", files: ["WaveSimViz.jsx"], detail: "The SignalFlowTab and WaveInterferenceTab canvas elements set their buffer dimensions to CSS logical pixels without accounting for window.devicePixelRatio. On retina/high-DPI displays (dpr=2), this rendered at half resolution causing blurry text and graphics. Applied the same dpr-aware pattern used in SupercriticalViz, TwinOscillatorSimViz, and RHRigorViz: scale canvas.width/height by dpr, apply ctx.scale(dpr, dpr), and draw using logical coordinates." },
  { id: 182, timestamp: "2026-03-03T23:59:00Z", category: "accuracy", summary: "Fix Spectral Decomposition formula equating complex x^ρ/ρ with real cosine (missing conjugate pair and factor of 2)", files: ["HamiltonianPage.jsx"], detail: "The Spectral Decomposition card on the Hamiltonian page displayed x^ρ/ρ = (x^{1/2}/√(γ²+1/4))cos(γ log x − arg ρ), equating a complex number with a real cosine. The real cosine form only arises when pairing conjugate zeros ρ and ρ̄: x^ρ/ρ + x^{ρ̄}/ρ̄ = 2Re(x^ρ/ρ). Fixed the formula to show the conjugate pair on the left-hand side with the correct factor of 2, and updated the text from 'Each nontrivial zero' to 'Each conjugate pair of nontrivial zeros' with amplitude 2/|ρ| instead of 1/|ρ|." },
  { id: 183, timestamp: "2026-03-03T12:00:00Z", category: "ux", summary: "Show largest prime (p_max) next to Primes slider count in all three FourierDomainViz tabs", files: ["FourierDomainViz.jsx"], detail: "The Primes sliders in FourierDomainViz's three tabs (Frequency Response, Spectral Energy, Prime Harmonics) displayed only the count (e.g. '12') without indicating the largest included prime. This was inconsistent with the p_max companion display already added to HamiltonianViz, AnimatedModesViz, EulerProductViz, WaveSimViz, SupercriticalViz, and RHRigorViz. Added '(up to p=N)' in subdued gray text next to all three slider values, so users immediately know the frequency range of the oscillator chain." },
  { id: 184, timestamp: "2026-03-03T12:30:00Z", category: "performance", summary: "Memoize prime gap data array in PrimeGapCouplingViz to avoid recomputing on mode switch and resize", files: ["PrimeGapCouplingViz.jsx"], detail: "The PrimeGapCouplingViz computed the primes array and gap/coupling data inside the draw() callback, which runs on every mode switch and window resize. With 200 primes, this meant 199 primeFrequency() calls (each involving Math.log) were repeated unnecessarily when only the display mode or window size changed. Extracted the data computation into a useMemo with [numPrimes] dependency, so switching between coupling/gap/frequency modes and resizing the window reuse the cached data instead of recomputing it." },
  { id: 185, timestamp: "2026-03-03T13:00:00Z", category: "performance", summary: "Memoize group delay computation in PhaseDelayTab to avoid recomputing oscillator stages on resize", files: ["WaveSimViz.jsx"], detail: "The PhaseDelayTab computed per-prime group delays (4 oscillatorStage calls per prime, up to 200 total) inside the draw() callback, which fires on every window resize via the parent's resize listener. Since the delays depend only on sigma, t, and numPrimes — not on SVG dimensions — resizes redundantly recomputed all oscillator math. Extracted the delays array into a useMemo keyed on [sigma, t, numPrimes], so draw() becomes a pure D3 rendering pass that reuses cached delay data when only the viewport changes." },
  { id: 186, timestamp: "2026-03-03T13:30:00Z", category: "content", summary: "Add 'What to Explore' guide card to ControlTheoryPage for Nyquist, Bode, and Scattering visualizations", files: ["ControlTheoryPage.jsx"], detail: "The ControlTheoryPage had two advanced visualizations (NyquistBodeViz and ScatteringMatrixViz) with multiple interactive modes but no exploration guide, unlike FourierPage, HamiltonianPage, ModesPage, StatisticsPage, and SupercriticalPage which all have 'What to Explore' cards. Added an amber-bordered guide card with four bullet points: Nyquist plot (watch encirclement of -1 as σ moves off 0.5), Bode diagram (0 dB marginal stability at critical line), scattering magnitude (|χ|=1 crossing steepens near zeros), and reflection coefficient (Γ vanishing at σ=0.5 for perfect matching)." },
  { id: 187, timestamp: "2026-03-03T14:00:00Z", category: "content", summary: "Add Davenport-Heilbronn counterexample exploration entry showing why functional equation alone is insufficient for RH", files: ["explorations.js"], detail: "Added exploration exp-036 on the Davenport-Heilbronn zeta function — the key counterexample that any RH proof strategy must handle. This function is a linear combination of two Dirichlet L-functions that satisfies a functional equation (lossless bridge) yet has zeros off σ=1/2. In oscillator terms, it is a superposition of two chain outputs, not a single Euler-product chain, so it lacks per-prime factorization. The entry explains the construction, why it defeats bridge-only arguments, and identifies the Euler product's multiplicative structure as the missing ingredient. Linked from exp-001 (Euler product), exp-017 (Beurling primes), and exp-035 (Dirichlet L-functions)." },
  { id: 188, timestamp: "2026-03-03T14:30:00Z", category: "bug", summary: "Fix waveform off-by-one causing curves to stop one sample short of rightmost x-axis tick in AnimatedModesViz", files: ["AnimatedModesViz.jsx"], detail: "The per-prime waveform and superposition drawing loops used i/xSteps for the fractional position, which with xSteps=200 gave a maximum frac of 199/200=0.995 instead of 1.0. This meant waveforms stopped ~3.5px short of the rightmost tick label (e^6), and the superposition fill path created a visible vertical step artifact at the right edge where it closed to the full-width baseline. Changed all three loops to use i/(xSteps-1) so the last sample reaches frac=1.0, aligning with the x-axis tick marks." },
  { id: 189, timestamp: "2026-03-03T15:00:00Z", category: "bug", summary: "Fix hardcoded devicePixelRatio=2 in AnimatedModesViz and EnergyLandscapeViz causing wrong canvas scaling on non-retina displays", files: ["AnimatedModesViz.jsx", "EnergyLandscapeViz.jsx"], detail: "Both AnimatedModesViz and EnergyLandscapeViz hardcoded `const dpr = 2` instead of querying `window.devicePixelRatio`. On standard-resolution displays (dpr=1), this doubled the canvas buffer size and applied 2x scaling via setTransform/ctx.scale, wasting GPU memory and causing the canvas to render at the wrong resolution. On 3x displays (some Android phones), it under-rendered at 2x. All other canvas components in the app (WaveSimViz, SupercriticalViz, TwinOscillatorSimViz, RHRigorViz) correctly use `window.devicePixelRatio || 1`. Replaced the hardcoded value with the standard pattern." },
  { id: 190, timestamp: "2026-03-03T15:30:00Z", category: "accuracy", summary: "Fix Wave Interference explainer wrongly claiming difference is near zero at σ=0.5", files: ["WaveSimViz.jsx"], detail: "The Wave Interference tab explainer said 'at σ=0.5 this should be near zero (matched amplitudes from direct/dual symmetry).' This is incorrect: at σ=0.5, direct s=[0.5,t] and dual s*=[0.5,−t] produce equal magnitudes per stage but conjugate (opposite-sign) phases. The difference wave equals 2·mag·cos(ωx+...)·sin(φ), which is generically nonzero whenever φ≠0. Replaced the misleading claim with the correct statement that amplitudes match but phases are conjugate-reflected, so the bottom panel measures phase asymmetry rather than amplitude mismatch." },
  { id: 191, timestamp: "2026-03-03T16:00:00Z", category: "ux", summary: "Show largest prime (p_max) next to Primes slider count in PrimeGapCouplingViz", files: ["PrimeGapCouplingViz.jsx"], detail: "The Primes slider in PrimeGapCouplingViz displayed only the count (e.g. '60') without indicating the largest included prime. Since the coupling strength, gap distribution, and frequency spectrum all depend on which primes are in the chain, users need to know p_max at a glance. Added a parenthetical '(up to p=N)' in subdued gray text using the already-computed primes array from useMemo, matching the pattern used in HamiltonianViz, AnimatedModesViz, EulerProductViz, WaveSimViz, SupercriticalViz, RHRigorViz, and FourierDomainViz." },
  { id: 192, timestamp: "2026-03-03T16:30:00Z", category: "visual", summary: "Add pass/fail legend to MultiZeroTab scatter plot in TwinOscillatorSimViz", files: ["TwinOscillatorSimViz.jsx"], detail: "The MultiZeroTab scatter plot colored dots green for pass and red for fail but had no legend explaining the color coding. Users had to read the explainer text or the results table to understand what the colors meant. Added a compact two-row legend in the top-right of the scatter chart with color-matched circle swatches and labels: 'Pass (|σ*−½| < 0.01)' in green and 'Fail' in red, using the same semi-transparent background panel style as legends in other visualizations." },
  { id: 193, timestamp: "2026-03-03T17:00:00Z", category: "bug", summary: "Fix hardcoded devicePixelRatio=2 in ZetaLandscapeViz causing wrong canvas scaling on non-retina displays", files: ["ZetaLandscapeViz.jsx"], detail: "Both drawCriticalLine and drawHeatmap in ZetaLandscapeViz used `canvas.clientWidth * 2` and `ctx.scale(2, 2)` instead of querying `window.devicePixelRatio`. On standard-resolution displays (dpr=1), this doubled the canvas buffer size and applied 2x scaling, wasting GPU memory and causing incorrect resolution. On 3x displays, it under-rendered at 2x. This was the same bug previously fixed in AnimatedModesViz and EnergyLandscapeViz (#189) but missed in ZetaLandscapeViz. Replaced the hardcoded `* 2` and `scale(2, 2)` with the standard `dpr = window.devicePixelRatio || 1` pattern used by all other canvas components." },
  { id: 194, timestamp: "2026-03-03T17:30:00Z", category: "performance", summary: "Memoize directLadder, dualLadder, and losslessBridge data in OscillatorChainViz to avoid recomputing on resize and stage click", files: ["OscillatorChainViz.jsx"], detail: "The OscillatorChainViz computed directLadder, dualLadder, losslessBridge, and getPrimes inside the draw() callback, which runs on every window resize and selectedStage click. With 50 primes, this meant ~100 oscillator stage evaluations plus a bridge computation wasted each time only the viewport or selection changed. Extracted all data computation into a useMemo keyed on [sigma, t, numPrimes] so draw() becomes a pure D3 rendering pass that reuses cached data when only the window size or selected stage changes." },
  { id: 195, timestamp: "2026-03-03T18:00:00Z", category: "content", summary: "Add 'What to Explore' guide card to ZetaPage for Critical Line and Heatmap modes", files: ["ZetaPage.jsx"], detail: "The ZetaPage was the only visualization page without a 'What to Explore' guide card. Users had two interactive modes (Critical Line Z(t) and |ζ(s)| Heatmap) plus t-range sliders but no guidance on what to look for. Added a cyan-bordered card with three bullet points: Critical Line mode (oscillation frequency, sign-change zeros, comparison to γₙ table), Heatmap mode (dark valleys at σ=½, zero packing at higher t), and Colorbar & scale (magnitude interpretation near zeros and the pole at s=1)." },
  { id: 196, timestamp: "2026-03-03T18:30:00Z", category: "accuracy", summary: "Fix ScatteringMatrixViz phase explainer describing phase-vs-t behavior when chart shows phase-vs-σ", files: ["ScatteringMatrixViz.jsx"], detail: "The phase mode explainer in ScatteringMatrixViz described 'phase changes of π between consecutive zeros' and 'total phase accumulation up to height t determines N(T) ~ θ(T)/π' — both properties of arg(χ) as a function of t along the critical line. But the chart actually plots arg(χ(σ+it)) as a function of σ for fixed t, so those statements described the wrong variable. Replaced with correct description: at σ=½ the phase equals −2θ(t), and away from the critical line it combines contributions from Γ(1−s), 2^s π^{s−1}, and sin(πs/2). Updated the 'Look for' to match what the σ-axis chart actually shows." },
  { id: 197, timestamp: "2026-03-03T19:00:00Z", category: "ux", summary: "Show highest zero frequency (γ_max) next to Zeros Used slider in LiCriterionViz", files: ["LiCriterionViz.jsx"], detail: "The Zeros Used slider in LiCriterionViz displayed only the count (e.g. '50') without indicating what frequency range of nontrivial zeros is covered. Since the Li coefficients λₙ and de Bruijn-Newman scatter depend critically on which zeros are summed over, users need to know γ_max at a glance. Added a parenthetical '(γ_max ≈ N)' in subdued gray text next to the slider value, matching the pattern already used in GUEStatisticsViz (#116) and ExplicitFormulaViz (#91)." },
  { id: 198, timestamp: "2026-03-03T19:30:00Z", category: "visual", summary: "Add legend to Hamiltonian test chart in RHRigorViz showing dot colors, trajectory line, and zero bands", files: ["RHRigorViz.jsx"], detail: "The Hamiltonian minimization test chart in RHRigorViz had five distinct visual elements — green dashed reference line (σ=½), blue σ* trajectory line, red-to-green gradient dots (deviation magnitude), outlined circles (near-zero points), and green vertical bands (ζ zero locations) — but no legend explaining any of them. Users had to guess what colors and shapes meant. Added a compact semi-transparent legend panel in the lower-right of the chart with color-matched swatches for all five elements, matching the legend style used in other visualizations." },
  { id: 199, timestamp: "2026-03-03T20:00:00Z", category: "performance", summary: "Memoize per-prime energy curves in PerPrimeTab to avoid recomputing 640+ oscillatorStage calls on resize", files: ["TwinOscillatorSimViz.jsx"], detail: "The PerPrimeTab in TwinOscillatorSimViz computed per-prime energy curves (primes × 81 steps = 640+ oscillatorStage calls) inside the draw() callback, which fires on every window resize. Since the curves and minima depend only on tValue and numPrimes — not on SVG dimensions — resizes redundantly recomputed all oscillator math. Extracted the curves and minima computation into a useMemo keyed on [tValue, numPrimes], so draw() becomes a pure D3 rendering pass that reuses cached data when only the viewport changes." },
  { id: 200, timestamp: "2026-03-03T20:30:00Z", category: "content", summary: "Add Hadamard product exploration entry showing the zero-factorization dual to the Euler product", files: ["explorations.js"], detail: "Added exploration exp-037 on the Hadamard product formula — the factorization of ξ(s) as a product over its nontrivial zeros, dual to the Euler product factoring over primes. The entry explains the circuit interpretation (cascade form vs pole-zero form), how RH appears in both factorizations (Q=1 per prime vs all zeros on σ=½), and the connection to the Li criterion as a passivity condition on the zero product. Linked from exp-001 (Euler product), exp-009 (explicit formula), and exp-022 (Li criterion)." },
  { id: 201, timestamp: "2026-03-03T21:00:00Z", category: "bug", summary: "Fix GradientDescentTab canvas not redrawing on window resize causing stretched/blurry display", files: ["TwinOscillatorSimViz.jsx"], detail: "The GradientDescentTab in TwinOscillatorSimViz used a canvas element (width: 100%) but had no window resize event listener, unlike every other canvas-based visualization in the app and every other tab in TwinOscillatorSimViz (PerPrimeTab, ConvergenceTab, BridgeTab all have resize handlers). When the browser was resized, the canvas CSS dimensions changed but the pixel buffer remained at the old size, causing the gradient descent chart to appear stretched and blurry. Added a resize useEffect that redraws with the current curve, path, and step data." },
  { id: 202, timestamp: "2026-03-03T22:00:00Z", category: "accuracy", summary: "Fix explicit formula explainer claiming arg(ρ) ≈ π/2 'for all zeros' and missing factor of 2", files: ["ExplicitFormulaViz.jsx"], detail: "The explainer text stated 'arg(ρ) ≈ π/2 for all zeros' and gave the asymptotic form as x^{1/2}sin(γ log x)/γ. Both claims are imprecise: arg(ρ) = arctan(2γ), which only approaches π/2 for large γ (it's 87.97° for the first zero γ₁≈14.13), and the correct asymptotic coefficient is 2/γ (from 2/|ρ| with |ρ|→γ), not 1/γ. Replaced the vague 'for all zeros' with the exact expressions arctan(2γ)→π/2 and |ρ|=√(1/4+γ²)→γ, qualified as 'for large γ', and added the missing factor of 2." },
  { id: 203, timestamp: "2026-03-03T22:30:00Z", category: "ux", summary: "Show largest prime (p_max) next to Primes slider count in TwinOscillatorSimViz and OscillatorChainViz", files: ["TwinOscillatorSimViz.jsx", "OscillatorChainViz.jsx"], detail: "The Primes sliders in TwinOscillatorSimViz (Per-Prime Energy, Gradient Descent, and Multi-Zero tabs) and OscillatorChainViz displayed only the count (e.g. '10') without indicating the largest included prime. Since the oscillator chain frequency range and Hamiltonian energy landscape depend on which primes are included, users need to know p_max at a glance. Added '(up to p=N)' in subdued gray text to all four slider locations, matching the pattern already used in HamiltonianViz, AnimatedModesViz, EulerProductViz, WaveSimViz, SupercriticalViz, RHRigorViz, FourierDomainViz, and PrimeGapCouplingViz." },
  { id: 204, timestamp: "2026-03-03T23:00:00Z", category: "accuracy", summary: "Fix WaveSimPage wrongly claiming Γ = (Z_dir − Z_dual)/(Z_dir + Z_dual) = 0 at σ=½; impedances are conjugate-matched, not equal", files: ["WaveSimPage.jsx"], detail: "The WaveSimPage displayed a prominent formula claiming the reflection coefficient Γ = (Z_dir − Z_dual)/(Z_dir + Z_dual) = 0 at σ = 1/2, and the explainer card asserted Z_dir = Z_dual. Both are mathematically wrong: at σ = 1/2, the dual ladder evaluates at s* = (0.5, −t), making Z_dual = Z_dir* (complex conjugate), not Z_dual = Z_dir. So Γ = 2i·Im(Z)/(2·Re(Z)) ≠ 0. Replaced the false Γ = 0 claim with the correct conjugate-match condition Z_dir = Z*_dual (equal magnitudes, reflected phases), and combined it with the bridge losslessness |χ| = 1 which is the actual zero-reflection condition." },
  { id: 205, timestamp: "2026-03-03T23:30:00Z", category: "visual", summary: "Add horizontal gridlines to both magnitude and phase panels in FrequencyResponseTab Bode diagram", files: ["FourierDomainViz.jsx"], detail: "The FrequencyResponseTab (Bode diagram) in FourierDomainViz had axis ticks on both the magnitude (dB) and phase (radians) panels but no horizontal gridlines, making it difficult to read values away from the y-axis. The Von Mangoldt Spectrum tab in the same component already had gridlines, creating an inconsistency. Added dashed #1e293b horizontal gridlines to both panels matching the app-wide style used in HamiltonianViz, PrimeGapCouplingViz, ExplicitFormulaViz, and ScatteringMatrixViz." },
  { id: 206, timestamp: "2026-03-03T23:45:00Z", category: "accuracy", summary: "Fix Spectral Energy explainer wrongly claiming impedance mismatch vanishes at σ=½ (it equals 2|Im Z|, not zero)", files: ["FourierDomainViz.jsx"], detail: "The Spectral Energy tab explainer said 'mismatch (red) vanishing' at σ=0.5 and attributed energy equality to the functional equation. Both are wrong: the red curve shows |Z_dir − Z_dual| (impedance mismatch), and at σ=½ the dual ladder evaluates at (0.5, −ω), making Z_dual = Z_dir* (complex conjugate). So |Z_dir − Z_dual| = 2|Im(Z)| which is generically nonzero. The energy equality (blue/orange overlap) comes from conjugate symmetry of the Euler factors, not the functional equation. Corrected the text to explain the mismatch measures imaginary-part asymmetry and is minimized but not zero at σ=½." },
  { id: 207, timestamp: "2026-03-03T23:55:00Z", category: "bug", summary: "Fix Poisson reference line slope in number-variance plot drawing Σ²=L/4 instead of Σ²=L", files: ["GUEStatisticsViz.jsx"], detail: "The Poisson reference line in the GUE Statistics number-variance mode was drawn from (L=0, Σ²=0) to (L=6, Σ²=yMax) where yMax is typically 1-2. This gave slope yMax/6 ≈ 0.2-0.3 instead of the correct slope 1 for Σ²=L, making the Poisson prediction appear almost flat. The bug was that x2 was always x(6) (right edge) while y2 was clamped to y(yMax), distorting the line when yMax < 6. Fixed by ending the line at x(min(6, yMax)) so it maintains slope 1 in data coordinates and exits the chart cleanly at the top of the y-axis. This makes the dramatic difference between Poisson (linear) and GUE (logarithmic) number variance visually clear." },
  { id: 208, timestamp: "2026-03-03T12:00:00Z", category: "performance", summary: "Precompute per-prime constants in AnimatedModesViz to avoid redundant Math.log/sqrt/cos calls per animation frame", files: ["AnimatedModesViz.jsx"], detail: "The AnimatedModesViz draw() callback ran at ~60fps and recomputed getPrimes(), primeFrequency() (which calls Math.log), Math.cos(gamma*log(p))/Math.sqrt(p) amplitude, and HSL color hue for every prime on every frame. These values depend only on numPrimes and zeroIndex, not on time. Extracted them into a useMemo keyed on [numPrimes, zeroIndex], eliminating up to 50 redundant getPrimes calls and 50 primeFrequency/Math.log/Math.sqrt/Math.cos evaluations per frame (3000/sec at 60fps with 50 primes)." },
  { id: 209, timestamp: "2026-03-03T23:59:00Z", category: "ux", summary: "Add γ_max display next to Zeros slider in SupercriticalViz Heat Flow tab", files: ["SupercriticalViz.jsx"], detail: "The Zeros slider in the Heat Flow tab of SupercriticalViz displayed only the count (e.g. '25') without indicating the highest zero frequency included. All other zero-count sliders in the app (GUEStatisticsViz, ExplicitFormulaViz, LiCriterionViz) already show γ_max next to the count. Added the same '(γ_max ≈ N)' companion text in subdued gray, so users immediately know the frequency range of the zeros used in the de Bruijn-Newman heat flow computation." },
  { id: 210, timestamp: "2026-03-04T00:30:00Z", category: "content", summary: "Add Selberg Central Limit Theorem exploration entry connecting Gaussian statistics to oscillator cascade", files: ["explorations.js"], detail: "Added exploration entry 'Selberg's Central Limit Theorem: Gaussian Statistics from Prime Oscillators' explaining how log ζ(½+it) is approximately Gaussian with variance ½ log log T. The entry derives this from approximate independence of prime oscillator stages over dyadic blocks, connects it to the cascade model (CLT for weakly correlated stages), links to Keating-Snaith moments, and explains why the slow √(log log T) growth reflects critical coupling Q=1." },
  { id: 211, timestamp: "2026-03-04T01:00:00Z", category: "visual", summary: "Add label and legend entry for R₂=1 reference line in pair-correlation plot", files: ["GUEStatisticsViz.jsx"], detail: "The pair-correlation tab in GUEStatisticsViz drew a dashed R₂=1 reference line but had no label or legend entry for it, making it unclear what the line represented. Added a 'R₂ = 1 (uncorrelated)' label positioned at the right end of the line and a matching dashed legend entry labeled 'R₂ = 1 (Poisson limit)'. This makes the plot self-explanatory: users can now see that the GUE pair correlation dips below 1 at short range (level repulsion) and approaches 1 at large range (independence), contrasted against the Poisson baseline." },
  { id: 212, timestamp: "2026-03-04T01:30:00Z", category: "performance", summary: "Memoize eulerProductPhaseAnalysis data in EulerPhaseTab to avoid recomputing 150-point scan on resize", files: ["SupercriticalViz.jsx"], detail: "The EulerPhaseTab in SupercriticalViz computed eulerProductPhaseAnalysis(tValue, [-1, 3], 150, numPrimes) — a 150-point scan evaluating Euler product magnitude, phase, and convergence for each σ — inside the draw() callback, which fires on every window resize. Since the data depends only on tValue and numPrimes (not viewport dimensions), resizes redundantly recomputed all 150 × numPrimes Euler factor evaluations. Extracted the computation into a useMemo keyed on [tValue, numPrimes] so draw() becomes a pure D3 rendering pass that reuses cached data when only the window size changes." },
  { id: 213, timestamp: "2026-03-04T02:00:00Z", category: "bug", summary: "Fix pair-correlation reference curve missing R₂(0)=0 boundary point due to loop starting at r=0.01", files: ["GUEStatisticsViz.jsx"], detail: "The GUE pair-correlation reference curve REF_R2_CURVE started its loop at r=0.01 instead of r=0, missing the mathematically critical boundary point R₂(0)=0. The pair-correlation function R₂(r) = 1 − sinc²(πr) must equal 0 at r=0 because sinc(0) = 1 by L'Hôpital's rule, representing perfect level repulsion (zero probability of coincident eigenvalues). Without this point, the reference curve appeared to start slightly above zero, misrepresenting the GUE prediction. Added an explicit {r:0, p:0} point at the start and adjusted the loop to begin at r=0.02 to maintain even spacing." },
];
